    #[test]
    fn grouped_selector_clocks_admission() {
        fn selected_native(index: usize) -> crate::value::Sample {
            let mut sample = crate::test_storage::counter(index);
            if index == 7 {
                sample.value = crate::value::SampleValue::FloatHistogram(Default::default());
            }
            sample
        }
        fn unselected_native(index: usize) -> crate::value::Sample {
            let mut sample = crate::test_storage::counter(index);
            if index == 6 {
                sample.value = crate::value::SampleValue::FloatHistogram(Default::default());
            }
            sample
        }
        for (body, admitted) in [
            ("sum by(id)(m_total)", 1),
            ("((avg without(member)(m_total)))", 1),
            ("sum by(__name__,id)(m_total)", 1),
            ("sum by(__type__,id)(m_total)", 1),
            ("sum by(__unit__,id)(m_total)", 1),
            ("avg without(member,__type__,__unit__)(m_total)", 1),
            ("count by(id)(m_total offset 1s)", 1),
            ("sum by(id)(m_total @ 8)", 0),
            ("sum by(id)(sum by(id,member)(m_total))", 2),
            ("sum by(id,__name__)(sum by(id,member)(m_total))", 2),
            ("sum by(id,__type__)(sum by(id,member)(m_total))", 2),
            ("sum by(id,__unit__)(sum by(id,member)(m_total))", 2),
            ("sum by(id)(sum by(id,member,__name__)(m_total))", 2),
            ("sum by(id)(sum by(id,member,__type__)(m_total))", 2),
            ("sum by(id)(sum by(id,member,__unit__)(m_total))", 2),
            (
                "sum without(member,__type__,__unit__)(sum by(id,member)(m_total))",
                2,
            ),
            ("sum by(id)(sum without(__type__,__unit__)(m_total))", 2),
            ("sum without(member)(sum by(id,member)(m_total))", 2),
            ("sum by(id)(sum without(member)(m_total))", 2),
            ("label_join(sum by(id)(m_total),\"service\",\"\",\"id\")", 1),
            (
                "label_replace((sum by(id)(m_total)),\"service\",\"$1\",\"id\",\"(.*)\")",
                1,
            ),
            (
                "abs(label_join(sum by(id)(m_total),\"service\",\"\",\"id\"))",
                0,
            ),
            (
                "label_join(abs(sum by(id)(m_total)),\"service\",\"\",\"id\")",
                0,
            ),
            (
                "label_join(label_join(sum by(id)(m_total),\"service\",\"\",\"id\"),\"zone\",\"\",\"id\")",
                0,
            ),
            (
                "label_join(sum by(id)(max by(id,member)(m_total)),\"service\",\"\",\"id\")",
                0,
            ),
            ("((sum by(id)(((max by(id,member)(m_total))))))", 2),
            (
                "sum by(id)(max by(id,member)(sum by(id,member)(m_total)))",
                0,
            ),
            ("abs(sum by(id)(max by(id,member)(m_total)))", 0),
            ("sum by(id)(max by(id,member)(m_total))+1", 0),
            (
                "sum by(id)(max by(id,member)(m_total))/sum by(id)(m_total)",
                0,
            ),
            ("abs(sum by(id)(m_total))", 0),
            ("sum by(id)(m_total)+1", 0),
            ("sum by(id)(m_total)/sum by(id)(m_total)", 0),
            ("histogram_quantile(0.5,sum by(id,le)(m_total))", 0),
            ("topk(1,m_total)", 0),
        ] {
            for settings in [
                options(false),
                options(true),
                EngineOptions {
                    delayed_name_removal: true,
                    ..EngineOptions::default()
                },
            ] {
                let delayed = settings.delayed_name_removal;
                for shape in ["float", "selected-native", "unselected-native", "empty"] {
                    let engine = Engine::default();
                    let control = Control::default();
                    let expression = format!("max_over_time(({body})[4s:2s])");
                    let compiled = engine
                        .compile(expression.as_bytes(), settings, &control)
                        .unwrap();
                    let mut provider = grouped_subquery_provider(1, 2);
                    for series in &mut provider.series {
                        match shape {
                            "selected-native" => series.source.sample = selected_native,
                            "unselected-native" => series.source.sample = unselected_native,
                            "empty" => series.source.count = 0,
                            _ => {}
                        }
                    }
                    let account = compiled.execution_accounting();
                    {
                        let header = compiled
                            .header(QueryRequest::Instant { time_ms: 8000 })
                            .unwrap();
                        let prepared = Prepared::new(
                            &compiled.expression,
                            &compiled.preprocessing,
                            header,
                            compiled.options.no_step_subquery_interval_ms,
                            &control,
                            &account,
                        )
                        .unwrap();
                        let header = prepared.evaluator_header();
                        prepared.activate(header, &control, &account).unwrap();
                        let options =
                            compiled.evaluation_options(header, header.start_ms, &prepared);
                        let bounds = crate::query_bounds::find(
                            &compiled.expression,
                            options,
                            &prepared,
                            &control,
                            &account,
                        )
                        .unwrap();
                        let scope = provider.open(bounds, &control).unwrap();
                        let catalog = Catalog::new(
                            &scope,
                            &compiled.expression,
                            &prepared,
                            options,
                            compiled.options.no_step_subquery_interval_ms,
                            &control,
                            &account,
                        )
                        .unwrap();
                        let rosters = compiled
                            .prepare_rosters(
                                &catalog,
                                &prepared,
                                bounds,
                                &control,
                                &account,
                                &mut Annotations::default(),
                            )
                            .unwrap();
                        let intervals = (0..compiled.expression.arena.nodes.len())
                            .filter_map(|index| rosters.group_replay(NodeId(index)))
                            .filter(|plan| plan.supports_interval())
                            .count();
                        // Offset moves the selected native tick onto the child grid.
                        let float_only = shape == "float"
                            || shape == "unselected-native" && !body.contains("offset")
                            || shape == "selected-native" && body.contains("offset");
                        assert_eq!(
                            intervals,
                            if !float_only {
                                0
                            } else if !delayed {
                                admitted
                            } else if matches!(
                                body,
                                "sum by(id)(m_total)"
                                    | "count by(id)(m_total offset 1s)"
                                    | "avg without(member,__type__,__unit__)(m_total)"
                            ) {
                                1
                            } else if matches!(
                                body,
                                "sum by(id)(sum by(id,member)(m_total))"
                                    | "((sum by(id)(((max by(id,member)(m_total))))))"
                                    | "sum without(member,__type__,__unit__)(sum by(id,member)(m_total))"
                                    | "sum by(id)(sum without(__type__,__unit__)(m_total))"
                            ) {
                                2
                            } else {
                                0
                            },
                            "{body} delayed={delayed} shape={shape}"
                        );
                    }
                    provider.assert_closed();
                    drop((account, compiled));
                    engine.accounting.snapshot().assert_memory_released();
                }
            }
        }
    }

