    #[test]
    fn nested_grouped_clocks_unequal_members() {
        fn point(index: usize) -> crate::value::Sample {
            let mut sample = crate::test_storage::counter(index);
            sample.value = crate::value::SampleValue::Float((index + 1) as f64);
            sample
        }
        for page in [1, 17, 1024] {
            for groups in [4, 16] {
                for leaf in ["m_total", "rate(m_total[3s])"] {
                    let engine = Engine::default();
                    let control = Control::default();
                    let expression =
                        format!("max_over_time((sum by(id)(sum by(id,member)({leaf})))[8s:1s])");
                    let query = engine
                        .compile(expression.as_bytes(), EngineOptions::default(), &control)
                        .unwrap();
                    let mut provider = FixtureProvider::new(16, page, groups * 3);
                    provider.filter_selectors = true;
                    for (position, series) in provider.series.iter_mut().enumerate() {
                        series.source.sample = point;
                        series.labels = vec![
                            (b"__name__".to_vec(), b"m_total".to_vec()),
                            (b"id".to_vec(), format!("{:06}", position / 3).into_bytes()),
                            (
                                b"member".to_vec(),
                                if position % 3 == 0 { b"a" } else { b"b" }.to_vec(),
                            ),
                            (b"replica".to_vec(), (position % 3).to_string().into_bytes()),
                        ];
                    }
                    let report = query.collect_reported(
                        &provider,
                        QueryRequest::Instant { time_ms: 16000 },
                        &control,
                    );
                    let result = report.result.as_ref().unwrap();
                    assert!(report.annotations.is_empty());
                    assert_eq!(result.series.len(), groups);
                    for (identity, row) in result.series.iter().enumerate() {
                        assert_eq!(row.labels.0.len(), 1);
                        assert_eq!(&*row.labels.0[0].name, b"id");
                        assert_eq!(&*row.labels.0[0].value, format!("{identity:06}").as_bytes());
                        assert_eq!(row.points.len(), 1);
                        assert_eq!(row.points[0].time_ms, 16000);
                        let expected: f64 = if leaf == "m_total" { 48.0 } else { 3.0 };
                        assert_eq!(float_bits(&row.points[0]), expected.to_bits());
                    }
                    provider.assert_closed();
                    drop((report, query));
                    engine.accounting.snapshot().assert_memory_released();
                }
            }
        }
    }

    #[test]
    fn projected_grouped_clocks_results() {
        for page in [1, 17, 1024] {
            for count in [4, 16] {
                for (leaf, scale) in [("m_total", 16.0), ("rate(m_total[3s])", 1.0)] {
                    for call in [
                        "label_join({group},\"service\",\"\",\"id\")",
                        "label_replace({group},\"service\",\"$1\",\"id\",\"(.*)\")",
                    ] {
                        let engine = Engine::default();
                        let control = Control::default();
                        let body = call.replace("{group}", &format!("sum by(id)({leaf})"));
                        let expression = format!("max_over_time(({body})[8s:1s])");
                        let query = engine
                            .compile(expression.as_bytes(), EngineOptions::default(), &control)
                            .unwrap();
                        let provider = grouped_subquery_provider(page, count);
                        let report = query.collect_reported(
                            &provider,
                            QueryRequest::Instant { time_ms: 16000 },
                            &control,
                        );
                        let result = report.result.as_ref().unwrap();
                        assert!(report.annotations.is_empty());
                        assert_eq!(result.series.len(), count);
                        let mut rows = result.series.iter().collect::<Vec<_>>();
                        rows.sort_by(|a, b| a.labels.0[0].value.cmp(&b.labels.0[0].value));
                        for (identity, row) in rows.into_iter().enumerate() {
                            let id = format!("{identity:06}");
                            assert_eq!(
                                row.labels
                                    .0
                                    .iter()
                                    .map(|v| (&*v.name, &*v.value))
                                    .collect::<Vec<_>>(),
                                vec![
                                    (b"id".as_slice(), id.as_bytes()),
                                    (b"service".as_slice(), id.as_bytes())
                                ]
                            );
                            assert_eq!(row.points.len(), 1);
                            assert_eq!(row.points[0].time_ms, 16000);
                            let expected: f64 = scale
                                * if identity.is_multiple_of(2) {
                                    6.0
                                } else {
                                    12.0
                                };
                            assert_eq!(float_bits(&row.points[0]), expected.to_bits());
                        }
                        provider.assert_closed();
                        drop((report, query));
                        engine.accounting.snapshot().assert_memory_released();
                    }
                }
            }
        }
    }

    #[test]
    fn nested_grouped_clocks_results() {
        grouped_selector_clocks_results_case(true);
    }

    fn grouped_selector_clocks_results_case(nested: bool) {
        for aggregate in [
            "sum", "avg", "count", "group", "min", "max", "stdvar", "stddev",
        ] {
            for page in [1, 17, 1024] {
                for count in [4, 16] {
                    let engine = Engine::default();
                    let control = Control::default();
                    let child = if nested {
                        "max by(id,member)(m_total)"
                    } else {
                        "m_total"
                    };
                    let expression = format!("max_over_time(({aggregate} by(id)({child}))[8s:1s])");
                    let query = engine
                        .compile(expression.as_bytes(), EngineOptions::default(), &control)
                        .unwrap();
                    let provider = grouped_subquery_provider(page, count);
                    let report = query.collect_reported(
                        &provider,
                        QueryRequest::Instant { time_ms: 16000 },
                        &control,
                    );
                    let result = report.result.as_ref().unwrap();
                    assert!(report.annotations.is_empty());
                    assert_eq!(result.series.len(), count);
                    let mut rows = result.series.iter().collect::<Vec<_>>();
                    rows.sort_by(|a, b| a.labels.0[0].value.cmp(&b.labels.0[0].value));
                    for (identity, row) in rows.into_iter().enumerate() {
                        assert_eq!(row.labels.0.len(), 1);
                        assert_eq!(&*row.labels.0[0].name, b"id");
                        assert_eq!(&*row.labels.0[0].value, format!("{identity:06}").as_bytes());
                        let even = identity.is_multiple_of(2);
                        let value: f64 = match aggregate {
                            "sum" => {
                                if even {
                                    96.0
                                } else {
                                    192.0
                                }
                            }
                            "avg" => {
                                if even {
                                    48.0
                                } else {
                                    96.0
                                }
                            }
                            "count" => 2.0,
                            "group" => 1.0,
                            "min" => {
                                if even {
                                    32.0
                                } else {
                                    64.0
                                }
                            }
                            "max" => {
                                if even {
                                    64.0
                                } else {
                                    128.0
                                }
                            }
                            "stdvar" => {
                                if even {
                                    256.0
                                } else {
                                    1024.0
                                }
                            }
                            "stddev" => {
                                if even {
                                    16.0
                                } else {
                                    32.0
                                }
                            }
                            _ => unreachable!(),
                        };
                        assert_eq!(row.points.len(), 1);
                        assert_eq!(row.points[0].time_ms, 16000);
                        assert_eq!(float_bits(&row.points[0]), value.to_bits());
                    }
                    assert_eq!(report.observations.output_samples, count as u64);
                    assert_eq!(
                        report
                            .observations
                            .statistics
                            .samples
                            .total_queryable_samples,
                        (8 * count) as u64
                    );
                    if count == 16 && page == 17 {
                        assert!(report.observations.samples_fetched < 100_000);
                    }
                    assert!(
                        provider.series.iter().all(|series| series
                            .source
                            .counters
                            .peak
                            .load(Ordering::Relaxed)
                            == 1)
                    );
                    provider.assert_closed();
                    drop((report, query));
                    engine.accounting.snapshot().assert_memory_released();
                }
            }
        }
    }

