    #[test]
    fn grouped_histogram_discovery_preserves_changing_results_and_paged_reads() {
        for aggregate in ["sum", "avg"] {
            grouped_histogram_discovery_preserves_changing_results_and_paged_reads_case(
                aggregate, true,
            );
        }
    }

    fn grouped_histogram_discovery_preserves_changing_results_and_paged_reads_case(
        aggregate: &str,
        full_matrix: bool,
    ) {
        for &(rate_function, _) in grouped_clock_rates(full_matrix) {
            for &page in grouped_clock_pages(full_matrix) {
                for &delayed in if full_matrix {
                    &[false, true][..]
                } else {
                    &[false][..]
                } {
                    for (function, expected) in [
                        ("min", 10.0 / 11.0),
                        ("max", 1.0),
                        ("avg", (10.0 / 11.0 + 7.0) / 8.0),
                    ]
                    .into_iter()
                    .skip(if full_matrix { 0 } else { 1 })
                    .take(if full_matrix { 3 } else { 1 })
                    {
                        let engine = Engine::default();
                        let control = Control::default();
                        let query = engine.compile(
                            format!("{function}_over_time((histogram_quantile(.5,{aggregate} by(id,le)({rate_function}(duration_bucket[3s]))))[8s:1s])").as_bytes(),
                            options(delayed), &control,
                        ).unwrap();
                        let provider = grouped_histogram_provider(page, 2);
                        let report = query.collect_reported(
                            &provider,
                            QueryRequest::Instant { time_ms: 16000 },
                            &control,
                        );
                        let result = report.result.as_ref().unwrap();
                        assert!(report.annotations.is_empty());
                        assert_eq!(result.series.len(), 2);
                        let mut rows = result.series.iter().collect::<Vec<_>>();
                        rows.sort_by(|a, b| a.labels.0[0].value.cmp(&b.labels.0[0].value));
                        for (identity, row) in rows.into_iter().enumerate() {
                            assert_eq!(row.labels.0.len(), 1);
                            assert_eq!(&*row.labels.0[0].name, b"id");
                            assert_eq!(
                                &*row.labels.0[0].value,
                                format!("{identity:06}").as_bytes()
                            );
                            assert_eq!(row.points.len(), 1);
                            assert_eq!(row.points[0].time_ms, 16000);
                            let value = f64::from_bits(float_bits(&row.points[0]));
                            let expected = match aggregate {
                                "count" | "group" => 0.5,
                                "stdvar" => 1.0,
                                _ => expected,
                            };
                            assert!(
                                (value - expected).abs() < 1e-14,
                                "{function}/{rate_function}: {value} != {expected}"
                            );
                        }
                        assert_eq!(report.observations.output_samples, 2);
                        assert_eq!(
                            report
                                .observations
                                .statistics
                                .samples
                                .total_queryable_samples,
                            16
                        );
                        assert_eq!(
                            report.observations.memory[MemoryKind::Workspace as usize].current,
                            0
                        );
                        assert!(
                            provider.series.iter().all(|row| row
                                .source
                                .counters
                                .peak
                                .load(Ordering::Relaxed)
                                == 1)
                        );
                        provider.assert_closed();
                        drop((report, query));
                        engine.accounting.snapshot().assert_memory_released();
                    }
                }
            }
        }
    }

    #[test]
    fn grouped_histogram_discovery_preserves_every_required_delivery_read_failure() {
        for aggregate in ["sum", "avg"] {
            grouped_histogram_discovery_preserves_every_required_delivery_read_failure_case(
                aggregate, true,
            );
        }
    }

    fn grouped_histogram_discovery_preserves_every_required_delivery_read_failure_case(
        aggregate: &str,
        full_matrix: bool,
    ) {
        for &(rate_function, _) in grouped_clock_rates(full_matrix) {
            let request = QueryRequest::Instant { time_ms: 8000 };
            for &page in grouped_clock_pages(full_matrix) {
                let engine = Engine::default();
                let control = Control::default();
                let query = engine.compile(
                    format!("max_over_time((histogram_quantile(.5,{aggregate} by(id,le)({rate_function}(duration_bucket[3s]))))[4s:1s])").as_bytes(),
                    EngineOptions::default(), &control,
                ).unwrap();
                let calibration = grouped_histogram_provider(page, 2);
                let (rows, prepared, pairs) = float_map_join_preparation_with_discovery(
                    &query,
                    &calibration,
                    request,
                    &control,
                );
                assert_eq!((rows, pairs), (2, 0));
                let provider = grouped_histogram_provider(page, 2);
                let mut sink = RecordingSink::default();
                let report = query.execute_reported(&provider, request, &control, &mut sink);
                assert!(report.result.is_ok());
                assert!(sink.begun && sink.committed && !sink.aborted);
                let last = provider
                    .series
                    .iter()
                    .map(|row| row.source.counters.opened.load(Ordering::Relaxed))
                    .collect::<Vec<_>>();
                provider.assert_closed();
                drop(report);
                let mut faults = 0;
                for (position, (&first, &last)) in prepared.iter().zip(&last).enumerate() {
                    assert!(last > first);
                    for acquisition in first + 1..=last {
                        let mut provider = grouped_histogram_provider(page, 2);
                        provider.series[position].source.fail_acquisition = Some(acquisition);
                        let mut sink = RecordingSink::default();
                        let report =
                            query.execute_reported(&provider, request, &control, &mut sink);
                        assert!(
                            matches!(&report.result, Err(ExecutionError::Evaluation(EvaluationError::Storage(StorageError::Provider(bytes)))) if &**bytes == b"injected page failure")
                        );
                        assert!(sink.begun && sink.aborted && !sink.committed);
                        assert_eq!(
                            provider.series[position]
                                .source
                                .counters
                                .opened
                                .load(Ordering::Relaxed),
                            acquisition
                        );
                        report.assert_retained_callback_error_memory();
                        provider.assert_closed();
                        faults += 1;
                    }
                }
                println!(
                    "grouped-histogram-discovery function={rate_function} page={page} required-delivery-faults={faults}"
                );
                drop(query);
                engine.accounting.snapshot().assert_memory_released();
            }
        }
    }

    #[test]
    fn grouped_histogram_discovery_keeps_cold_completion_fresh_reads_and_clearing() {
        for aggregate in ["sum", "avg"] {
            grouped_histogram_discovery_keeps_cold_completion_fresh_reads_and_clearing_case(
                aggregate, true,
            );
        }
    }

    fn grouped_histogram_discovery_keeps_cold_completion_fresh_reads_and_clearing_case(
        aggregate: &str,
        full_matrix: bool,
    ) {
        let expected = match aggregate {
            "count" | "group" => 0.5,
            "stdvar" => 1.0,
            _ => 5.0 / 7.0,
        };
        fn drive(
            compiled: &CompiledQuery,
            input: &FixtureProvider,
            stop: Option<(usize, bool)>,
            expected: f64,
        ) -> Vec<Vec<usize>> {
            let acquisitions = || {
                input
                    .series
                    .iter()
                    .map(|row| row.source.counters.opened.load(Ordering::Relaxed))
                    .collect::<Vec<_>>()
            };
            let control = Control::default();
            let account = compiled.execution_accounting();
            let mut landmarks = Vec::new();
            {
                let header = compiled
                    .header(QueryRequest::Instant { time_ms: 8000 })
                    .unwrap();
                let prepared = Prepared::new(
                    &compiled.expression,
                    &compiled.preprocessing,
                    header,
                    compiled.options.no_step_subquery_interval_ms,
                    &control,
                    &account,
                )
                .unwrap();
                let header = prepared.evaluator_header();
                prepared.activate(header, &control, &account).unwrap();
                let options = compiled.evaluation_options(header, header.start_ms, &prepared);
                let bounds = crate::query_bounds::find(
                    &compiled.expression,
                    options,
                    &prepared,
                    &control,
                    &account,
                )
                .unwrap();
                let scope = input.open(bounds, &control).unwrap();
                let catalog = Catalog::new(
                    &scope,
                    &compiled.expression,
                    &prepared,
                    options,
                    compiled.options.no_step_subquery_interval_ms,
                    &control,
                    &account,
                )
                .unwrap();
                let rosters = compiled
                    .prepare_rosters(
                        &catalog,
                        &prepared,
                        bounds,
                        &control,
                        &account,
                        &mut Annotations::default(),
                    )
                    .unwrap();
                let group = (0..compiled.expression.arena.nodes.len())
                    .find_map(|i| rosters.group_replay(NodeId(i)))
                    .unwrap();
                let histogram = (0..compiled.expression.arena.nodes.len())
                    .find_map(|i| rosters.histogram(NodeId(i)))
                    .unwrap();
                assert!(group.supports_interval() && histogram.routes_classic_inputs());
                assert!(
                    !group.has_interval() && !group.has_completion(),
                    "preparation credit must be cleared"
                );
                landmarks.push(acquisitions());
                let mut machine = Machine::new(
                    &catalog,
                    &compiled.expression,
                    compiled.expression.root,
                    options,
                    &control,
                    &account,
                    EvaluationMetadata {
                        prepared: &prepared,
                        rosters: &rosters,
                        timestamp_selectors: &compiled.timestamp_selectors,
                        data_bounds: bounds,
                        annotations: None,
                        binary_preparation: None,
                        histogram_preparation: None,
                        info_preparation: None,
                        count_preparation: None,
                    },
                );
                let mut outputs = 0;
                loop {
                    let stopping = stop.is_some_and(|(after, _)| outputs == after);
                    let cancelled = stopping && stop.unwrap().1;
                    let before = acquisitions();
                    if cancelled {
                        control.cancellation.cancel();
                    }
                    let next = machine.next();
                    if stopping {
                        let error = next.unwrap_err();
                        if cancelled {
                            assert!(matches!(
                                error,
                                EvaluationError::Interrupted(Interrupted::Cancelled)
                            ));
                            assert_eq!(acquisitions(), before);
                        } else {
                            assert!(
                                matches!(&error, EvaluationError::Storage(StorageError::Provider(bytes)) if &**bytes == b"injected page failure")
                            );
                        }
                        assert_eq!(group.has_interval(), outputs != 0);
                        drop(error);
                        break;
                    }
                    let Some(sample) = next.unwrap() else {
                        break;
                    };
                    assert!(group.has_interval());
                    assert!(
                        matches!(sample.value, OwnedValue::Float(value) if (value - expected).abs() < 1e-14)
                    );
                    outputs += 1;
                    landmarks.push(acquisitions());
                }
                if stop.is_none() {
                    assert_eq!(outputs, 2);
                }
                drop(machine);
                // Cancellation must not erase prior credit; ordinary cleanup owns its lifetime.
                rosters
                    .clear_replay_progress(&Control::default(), &account)
                    .unwrap();
                assert!(!group.has_interval() && !group.has_completion());
            }
            input.assert_closed();
            account.snapshot().assert_memory_released();
            landmarks
        }
        for disabled in [false, true] {
            let _fallback = disabled.then(crate::computed_groups::disable);
            for &page in grouped_clock_pages(full_matrix) {
                let engine = Engine::default();
                let control = Control::default();
                let query = engine.compile(
                format!("max_over_time((histogram_quantile(.5,{aggregate} by(id,le)(rate(duration_bucket[3s]))))[4s:1s])").as_bytes(),
                EngineOptions::default(), &control).unwrap();
                let calibration = grouped_histogram_provider(page, 2);
                let landmarks = drive(&query, &calibration, None, expected);
                assert_eq!(landmarks.len(), 3);
                let fresh = (0..8)
                    .filter(|&i| landmarks[2][i] > landmarks[1][i])
                    .collect::<Vec<_>>();
                assert_eq!(
                    fresh.len(),
                    if disabled { 4 } else { 0 },
                    "completed grouped bucket values replace warm contributor rereads"
                );
                let nonmember = (0..8).find(|i| !fresh.contains(i)).unwrap();
                assert!(
                    landmarks[1][nonmember] > landmarks[0][nonmember],
                    "cold discovery must read other histograms"
                );
                let mut faults = vec![(0, nonmember)];
                if disabled {
                    faults.push((1, fresh[0]));
                }
                for (after, target) in faults {
                    let mut input = grouped_histogram_provider(page, 2);
                    let acquisition = landmarks[after][target] + 1;
                    input.series[target].source.fail_acquisition = Some(acquisition);
                    assert_eq!(
                        drive(&query, &input, Some((after, false)), expected).len(),
                        after + 1
                    );
                    assert_eq!(
                        input.series[target]
                            .source
                            .counters
                            .opened
                            .load(Ordering::Relaxed),
                        acquisition
                    );
                }
                let input = grouped_histogram_provider(page, 2);
                assert_eq!(drive(&query, &input, Some((1, true)), expected).len(), 2);
                drop(query);
                engine.accounting.snapshot().assert_memory_released();
            }
        }
    }

    #[test]
    fn grouped_ratio_clocks_preserve_results_statistics_and_paged_reads() {
        for aggregate in ["sum", "avg"] {
            grouped_ratio_clocks_preserve_results_statistics_and_paged_reads_case(aggregate, true);
        }
    }

    fn grouped_ratio_clocks_preserve_results_statistics_and_paged_reads_case(
        aggregate: &str,
        full_matrix: bool,
    ) {
        for &(rate_function, _) in grouped_clock_rates(full_matrix) {
            for &page in grouped_clock_pages(full_matrix) {
                for &count in if full_matrix { &[4, 16][..] } else { &[2][..] } {
                    for &delayed in if full_matrix {
                        &[false, true][..]
                    } else {
                        &[false][..]
                    } {
                        for (function, factor) in [
                            ("max_over_time", 1.0),
                            ("min_over_time", 8.0 / 15.0),
                            ("avg_over_time", 11.5 / 15.0),
                            ("sum_over_time", 92.0 / 15.0),
                        ]
                        .into_iter()
                        .take(if full_matrix { 4 } else { 1 })
                        {
                            let engine = Engine::default();
                            let control = Control::default();
                            let expression = format!(
                                "{function}(({aggregate} by(id)({rate_function}(m_total[3s])) / {aggregate} by(id)({rate_function}(n_total[3s])))[8s:1s])"
                            );
                            let query = engine
                                .compile(expression.as_bytes(), options(delayed), &control)
                                .unwrap();
                            let provider = grouped_ratio_provider(page, count);
                            let report = query.collect_reported(
                                &provider,
                                QueryRequest::Instant { time_ms: 16000 },
                                &control,
                            );
                            let result = report.result.as_ref().unwrap();
                            assert!(report.annotations.is_empty());
                            assert_eq!(result.series.len(), count);
                            // Instant group order follows discovery; compare every label/value pair.
                            let mut rows = result.series.iter().collect::<Vec<_>>();
                            rows.sort_by(|a, b| a.labels.0[0].value.cmp(&b.labels.0[0].value));
                            for (identity, row) in rows.into_iter().enumerate() {
                                let id = format!("{identity:06}");
                                assert_eq!(
                                    row.labels
                                        .0
                                        .iter()
                                        .map(|label| (&*label.name, &*label.value))
                                        .collect::<Vec<_>>(),
                                    [(b"id".as_slice(), id.as_bytes())]
                                );
                                assert_eq!(row.points.len(), 1);
                                assert_eq!(row.points[0].time_ms, 16000);
                                let even = identity.is_multiple_of(2);
                                let value: f64 = match aggregate {
                                    "sum" | "avg" => {
                                        if even {
                                            45.0
                                        } else {
                                            180.0
                                        }
                                    }
                                    "count" | "group" => 1.0,
                                    "min" => {
                                        if even {
                                            60.0
                                        } else {
                                            240.0
                                        }
                                    }
                                    "max" => {
                                        if even {
                                            40.0
                                        } else {
                                            160.0
                                        }
                                    }
                                    "stdvar" => {
                                        if even {
                                            900.0
                                        } else {
                                            14400.0
                                        }
                                    }
                                    "stddev" => {
                                        if even {
                                            30.0
                                        } else {
                                            120.0
                                        }
                                    }
                                    _ => unreachable!(),
                                };
                                assert_eq!(float_bits(&row.points[0]), (value * factor).to_bits());
                            }
                            assert_eq!(report.observations.output_samples, count as u64);
                            assert_eq!(
                                report
                                    .observations
                                    .statistics
                                    .samples
                                    .total_queryable_samples,
                                (8 * count) as u64
                            );
                            assert_eq!(
                                report.observations.memory[MemoryKind::Workspace as usize].current,
                                0
                            );
                            assert!(provider.series.iter().all(|row| {
                                row.source.counters.peak.load(Ordering::Relaxed) == 1
                            }));
                            if !delayed && count == 16 && page == 17 && function == "max_over_time"
                            {
                                assert!(report.observations.samples_fetched < 200_000);
                            }
                            provider.assert_closed();
                            drop((report, query));
                            engine.accounting.snapshot().assert_memory_released();
                        }
                    }
                }
            }
        }
    }

