    fn grouped_subquery_clocks_preserve_results_statistics_and_paged_reads_case(
        aggregate: &str,
        full_matrix: bool,
    ) {
        for &(rate_function, rate_factor) in grouped_clock_rates(full_matrix) {
            for &page in grouped_clock_pages(full_matrix) {
                for &count in if full_matrix { &[4, 16][..] } else { &[2][..] } {
                    for &delayed in if full_matrix {
                        &[false, true][..]
                    } else {
                        &[false][..]
                    } {
                        for (function, factor) in [
                            ("max_over_time", 1.0),
                            ("min_over_time", 1.0),
                            ("avg_over_time", 1.0),
                            ("sum_over_time", 8.0),
                        ]
                        .into_iter()
                        .take(if full_matrix { 4 } else { 1 })
                        {
                            let engine = Engine::default();
                            let control = Control::default();
                            let expression = format!(
                                "{function}(({aggregate} by(id)({rate_function}(m_total[3s])))[8s:1s])"
                            );
                            let query = engine
                                .compile(expression.as_bytes(), options(delayed), &control)
                                .unwrap();
                            let provider = grouped_subquery_provider(page, count);
                            let report = query.collect_reported(
                                &provider,
                                QueryRequest::Instant { time_ms: 16000 },
                                &control,
                            );
                            let result = report.result.as_ref().unwrap();
                            assert!(report.annotations.is_empty());
                            assert_eq!(result.series.len(), count);
                            // Instant group order follows discovery; compare every label/value pair.
                            let mut rows = result.series.iter().collect::<Vec<_>>();
                            rows.sort_by(|a, b| a.labels.0[0].value.cmp(&b.labels.0[0].value));
                            for (identity, row) in rows.into_iter().enumerate() {
                                let id = format!("{identity:06}");
                                assert_eq!(
                                    row.labels
                                        .0
                                        .iter()
                                        .map(|label| (&*label.name, &*label.value))
                                        .collect::<Vec<_>>(),
                                    [(b"id".as_slice(), id.as_bytes())]
                                );
                                assert_eq!(row.points.len(), 1);
                                assert_eq!(row.points[0].time_ms, 16000);
                                let even = identity.is_multiple_of(2);
                                let value: f64 = match aggregate {
                                    "sum" => {
                                        if even {
                                            6.0
                                        } else {
                                            12.0
                                        }
                                    }
                                    "avg" => {
                                        if even {
                                            3.0
                                        } else {
                                            6.0
                                        }
                                    }
                                    "count" => 2.0,
                                    "group" => 1.0,
                                    "min" => {
                                        if even {
                                            2.0
                                        } else {
                                            4.0
                                        }
                                    }
                                    "max" => {
                                        if even {
                                            4.0
                                        } else {
                                            8.0
                                        }
                                    }
                                    "stdvar" => {
                                        if even {
                                            1.0
                                        } else {
                                            4.0
                                        }
                                    }
                                    "stddev" => {
                                        if even {
                                            1.0
                                        } else {
                                            2.0
                                        }
                                    }
                                    _ => unreachable!(),
                                };
                                let scale = match aggregate {
                                    "count" | "group" => 1.0,
                                    "stdvar" => rate_factor * rate_factor,
                                    _ => rate_factor,
                                };
                                assert_eq!(
                                    float_bits(&row.points[0]),
                                    (value * factor * scale).to_bits()
                                );
                            }
                            assert_eq!(report.observations.output_samples, count as u64);
                            assert_eq!(
                                report
                                    .observations
                                    .statistics
                                    .samples
                                    .total_queryable_samples,
                                (8 * count) as u64
                            );
                            assert_eq!(
                                report.observations.memory[MemoryKind::Workspace as usize].current,
                                0
                            );
                            assert!(provider.series.iter().all(|row| {
                                row.source.counters.peak.load(Ordering::Relaxed) == 1
                            }));
                            if !delayed && count == 16 && page == 17 && function == "max_over_time"
                            {
                                assert!(report.observations.samples_fetched < 100_000);
                            }
                            provider.assert_closed();
                            drop((report, query));
                            engine.accounting.snapshot().assert_memory_released();
                        }
                    }
                }
            }
        }
    }

    #[test]
    fn dry_progress_preserves_first_final_and_later_child_failures() {
        fn make_provider(page: usize) -> FixtureProvider {
            let mut provider = FixtureProvider::new(13, page, 4);
            // Fault indices must belong to this series, rather than the fixture's shared counter.
            for row in &mut provider.series {
                row.source.counters =
                    std::sync::Arc::new(crate::test_storage::CursorCounts::default());
            }
            provider
        }
        for page in [1, 17, 1024] {
            for delayed in [false, true] {
                let engine = Engine::default();
                let control = Control::default();
                let query = engine
                    .compile(
                        b"quantile_over_time(.5,(sum by(instance)(counter_total))[4s:1s])",
                        EngineOptions {
                            delayed_name_removal: delayed,
                            ..Default::default()
                        },
                        &control,
                    )
                    .unwrap();
                let request = QueryRequest::Range {
                    start_ms: 4000,
                    end_ms: 12000,
                    step_ms: 1000,
                };
                let calibration = make_provider(page);
                let (_, first) =
                    float_map_join_preparation(&query, &calibration, request, &control);
                let provider = make_provider(page);
                let (report, hits, saves) = crate::derived_progress::observe(false, || {
                    query.execute_reported(
                        &provider,
                        request,
                        &control,
                        &mut RecordingSink::default(),
                    )
                });
                assert!(report.result.is_ok());
                assert!(hits > 0 && saves > 0);
                drop(report);
                let last = provider
                    .series
                    .iter()
                    .map(|row| row.source.counters.opened.load(Ordering::Relaxed))
                    .collect::<Vec<_>>();
                provider.assert_closed();
                for (position, (&prepared, &total)) in first.iter().zip(&last).enumerate() {
                    assert!(total > prepared, "final data must be read afresh");
                    for acquisition in [prepared + 1, total] {
                        let mut provider = make_provider(page);
                        provider.series[position].source.fail_acquisition = Some(acquisition);
                        let mut sink = RecordingSink::default();
                        let report =
                            query.execute_reported(&provider, request, &control, &mut sink);
                        assert!(
                            matches!(&report.result,
                            Err(ExecutionError::Evaluation(EvaluationError::Storage(StorageError::Provider(bytes))))
                            if &**bytes == b"injected page failure"),
                            "page={page} delayed={delayed} position={position} acquisition={acquisition} prepared={prepared} total={total}: {:?}",
                            report.result
                        );
                        assert!(sink.begun && sink.aborted && !sink.committed);
                        report.assert_retained_callback_error_memory();
                        provider.assert_closed();
                    }
                }
                drop(query);
                engine.accounting.snapshot().assert_memory_released();
            }
        }
    }

