    fn grouped_ratio_clocks_keep_group_and_pair_completion_separate_case_with_delayed(
        aggregate: &str,
        full_matrix: bool,
        wrapper: Option<&str>,
        pair_intervals: bool,
        delayed: bool,
        cancel: bool,
    ) {
        for &(rate_function, _) in grouped_clock_rates(full_matrix) {
            for (page, fault) in grouped_clock_pages(full_matrix)
                .iter()
                .copied()
                .flat_map(|page| [(page, "none"), (page, "right"), (page, "both")])
            {
                let engine = Engine::default();
                let control = Control::default();
                let compiled = engine
                    .compile(
                        grouped_map_test_expression(format!("max_over_time(({aggregate} by(id)({rate_function}(m_total[3s])) / {aggregate} by(id)({rate_function}(n_total[3s])))[4s:1s])"), wrapper)
                            .as_bytes(),
                        EngineOptions { delayed_name_removal: delayed, ..EngineOptions::default() },
                        &control,
                    )
                    .unwrap();
                let calibration = grouped_ratio_provider(page, 2);
                let (_, baseline, pairs) = float_map_join_preparation_with_discovery(
                    &compiled,
                    &calibration,
                    QueryRequest::Instant { time_ms: 8000 },
                    &control,
                );
                assert_eq!(pairs, 1);
                let mut provider = grouped_ratio_provider(page, 2);
                if fault != "none" {
                    provider.series[4].source.fail_acquisition = Some(baseline[4] + 1);
                }
                if fault == "both" {
                    provider.series[0].source.fail_acquisition = Some(baseline[0] + 1);
                }
                let account = compiled.execution_accounting();
                {
                    let header = compiled
                        .header(QueryRequest::Instant { time_ms: 8000 })
                        .unwrap();
                    let prepared = Prepared::new(
                        &compiled.expression,
                        &compiled.preprocessing,
                        header,
                        compiled.options.no_step_subquery_interval_ms,
                        &control,
                        &account,
                    )
                    .unwrap();
                    let header = prepared.evaluator_header();
                    prepared.activate(header, &control, &account).unwrap();
                    let options = compiled.evaluation_options(header, header.start_ms, &prepared);
                    let bounds = crate::query_bounds::find(
                        &compiled.expression,
                        options,
                        &prepared,
                        &control,
                        &account,
                    )
                    .unwrap();
                    let scope = provider.open(bounds, &control).unwrap();
                    let catalog = Catalog::new(
                        &scope,
                        &compiled.expression,
                        &prepared,
                        options,
                        compiled.options.no_step_subquery_interval_ms,
                        &control,
                        &account,
                    )
                    .unwrap();
                    let rosters = compiled
                        .prepare_rosters(
                            &catalog,
                            &prepared,
                            bounds,
                            &control,
                            &account,
                            &mut Annotations::default(),
                        )
                        .unwrap();
                    let (binary, left, right) = compiled
                        .expression
                        .arena
                        .nodes
                        .iter()
                        .enumerate()
                        .find_map(|(index, node)| match node.expression {
                            Expr::Binary {
                                operator: TokenKind::DIV,
                                left,
                                right,
                                ..
                            } => Some((NodeId(index), left, right)),
                            _ => None,
                        })
                        .unwrap();
                    let left = rosters.group_replay(left);
                    let right = rosters.group_replay(right);
                    let binary = rosters.binary(binary).unwrap();
                    assert!(left.is_some_and(|plan| plan.supports_interval()));
                    assert!(right.is_some_and(|plan| plan.supports_interval()));
                    assert!(
                        !left.is_some_and(|plan| plan.has_interval())
                            && !right.is_some_and(|plan| plan.has_interval())
                            && !binary.has_completed_interval()
                    );
                    let mut machine = Machine::new(
                        &catalog,
                        &compiled.expression,
                        compiled.expression.root,
                        options,
                        &control,
                        &account,
                        EvaluationMetadata {
                            prepared: &prepared,
                            rosters: &rosters,
                            timestamp_selectors: &compiled.timestamp_selectors,
                            data_bounds: bounds,
                            annotations: None,
                            binary_preparation: None,
                            histogram_preparation: None,
                            info_preparation: None,
                            count_preparation: None,
                        },
                    );
                    if fault != "none" {
                        assert!(
                            matches!(machine.next(), Err(EvaluationError::Storage(StorageError::Provider(bytes))) if &*bytes == b"injected page failure")
                        );
                        assert_eq!(
                            left.is_some_and(|plan| plan.has_interval()),
                            fault == "right",
                            "{fault}"
                        );
                        assert!(
                            !right.is_some_and(|plan| plan.has_interval())
                                && !binary.has_completed_interval()
                        );
                        assert_eq!(
                            provider.series[4]
                                .source
                                .counters
                                .opened
                                .load(Ordering::Relaxed),
                            baseline[4] + usize::from(fault == "right")
                        );
                    } else {
                        let mut rows = 0;
                        while machine.next().unwrap().is_some() {
                            rows += 1;
                            if cancel {
                                control.cancellation.cancel();
                                assert!(matches!(
                                    machine.next(),
                                    Err(EvaluationError::Interrupted(
                                        crate::storage::Interrupted::Cancelled
                                    ))
                                ));
                                break;
                            }
                        }
                        assert_eq!(rows, if cancel { 1 } else { 2 });
                        let subquery = compiled
                            .expression
                            .arena
                            .nodes
                            .iter()
                            .position(|node| matches!(node.expression, Expr::Subquery { .. }))
                            .unwrap();
                        let grid = prepared
                            .subquery_scope(NodeId(subquery), &Control::default(), &account)
                            .unwrap();
                        assert_eq!(grid.end_ms, 8000);
                        for index in 0..if cancel { 0 } else { grid.steps().unwrap() } {
                            let time_ms = grid.start_ms + index * grid.interval_ms;
                            let key = crate::vector_matching::ReplayKey::new(
                                compiled.evaluation_options(
                                    grid.header(header),
                                    time_ms,
                                    &prepared,
                                ),
                                index,
                                prepared.lookback_ns(compiled.options.lookback_ms),
                                bounds,
                            );
                            assert!(
                                left.is_some_and(|plan| plan.interval_contains(key)),
                                "left operand at {time_ms}"
                            );
                            assert!(
                                right.is_some_and(|plan| plan.interval_contains(key)),
                                "right operand at {time_ms}"
                            );
                            assert_eq!(
                                binary.completed_interval_contains(key),
                                pair_intervals && time_ms < grid.end_ms,
                                "only actual binary completion earns clock {time_ms}"
                            );
                            assert_eq!(binary.prefix_interval_contains(key), !pair_intervals);
                        }
                    }
                    drop(machine);
                    rosters
                        .clear_replay_progress(&Control::default(), &account)
                        .unwrap();
                    assert!(
                        !left.is_some_and(|plan| plan.has_interval())
                            && !left.is_some_and(|plan| plan.has_completion())
                    );
                    assert!(
                        !right.is_some_and(|plan| plan.has_interval())
                            && !right.is_some_and(|plan| plan.has_completion())
                    );
                    assert!(
                        !binary.has_completed_interval()
                            && !binary.has_completed_pair_discovery()
                            && !binary.has_prefix_interval()
                    );
                }
                provider.assert_closed();
                drop((account, compiled));
                engine.accounting.snapshot().assert_memory_released();
            }
        }
    }

