    #[test]
    fn nested_grouped_clocks_completion() {
        for cancel in [false, true] {
            grouped_clocks_completion_case("sum", true, None, true, cancel, false);
            grouped_clocks_completion_case(
                "sum",
                false,
                Some("sum by(id)(max by(id,member)(m_total))"),
                true,
                cancel,
                false,
            );
        }
    }

    #[test]
    fn nested_grouped_clocks_first_failure_has_no_credit() {
        grouped_clocks_completion_case("sum", false, None, true, false, true);
        grouped_clocks_completion_case(
            "sum",
            false,
            Some("sum by(id)(max by(id,member)(m_total))"),
            true,
            false,
            true,
        );
    }

    #[test]
    fn nested_grouped_clocks_failures() {
        for body in [
            "sum by(id)(max by(id,member)(m_total))",
            "sum by(id)(max by(id,member)(rate(m_total[3s])))",
        ] {
            grouped_subquery_clocks_preserve_every_required_delivery_read_failure_case(
                "sum",
                false,
                Some(body),
            );
        }
    }

    fn grouped_clocks_completion_case(
        aggregate: &str,
        full_matrix: bool,
        wrapper: Option<&str>,
        nested: bool,
        cancel: bool,
        fault: bool,
    ) {
        grouped_clocks_completion_case_with_delayed(
            aggregate,
            full_matrix,
            wrapper,
            nested,
            cancel,
            fault,
            false,
        );
    }

    fn grouped_clocks_completion_case_with_delayed(
        aggregate: &str,
        full_matrix: bool,
        wrapper: Option<&str>,
        nested: bool,
        cancel: bool,
        fault: bool,
        delayed: bool,
    ) {
        grouped_clocks_completion_case_with_options(
            aggregate,
            full_matrix,
            wrapper,
            nested,
            cancel,
            fault,
            options(delayed),
        );
    }

    fn grouped_clocks_completion_case_with_options(
        aggregate: &str,
        full_matrix: bool,
        wrapper: Option<&str>,
        nested: bool,
        cancel: bool,
        fault: bool,
        settings: EngineOptions,
    ) {
        // Exercise actual endpoint truncation; the default drained-child path has separate completion checks.
        let _fallback = crate::evaluator::disable_drained_child();
        for &(rate_function, _) in grouped_clock_rates(full_matrix) {
            for &page in grouped_clock_pages(full_matrix) {
                let engine = Engine::default();
                let control = Control::default();
                let leaf = format!("{rate_function}(m_total[3s])");
                let leaf = if nested {
                    format!("max by(id,member)({leaf})")
                } else {
                    leaf
                };
                let compiled = engine
                    .compile(
                        grouped_map_test_expression(
                            format!("max_over_time(({aggregate} by(id)({leaf}))[4s:1s])"),
                            wrapper,
                        )
                        .as_bytes(),
                        settings,
                        &control,
                    )
                    .unwrap();
                let mut provider = grouped_subquery_provider(page, 2);
                if fault {
                    let calibration = grouped_subquery_provider(page, 2);
                    let (_, prepared) = float_map_join_preparation(
                        &compiled,
                        &calibration,
                        QueryRequest::Instant { time_ms: 8000 },
                        &control,
                    );
                    provider.series[0].source.fail_acquisition = Some(prepared[0] + 1);
                }
                let account = compiled.execution_accounting();
                {
                    let header = compiled
                        .header(QueryRequest::Instant { time_ms: 8000 })
                        .unwrap();
                    let prepared = Prepared::new(
                        &compiled.expression,
                        &compiled.preprocessing,
                        header,
                        compiled.options.no_step_subquery_interval_ms,
                        &control,
                        &account,
                    )
                    .unwrap();
                    let header = prepared.evaluator_header();
                    prepared.activate(header, &control, &account).unwrap();
                    let options = compiled.evaluation_options(header, header.start_ms, &prepared);
                    let bounds = crate::query_bounds::find(
                        &compiled.expression,
                        options,
                        &prepared,
                        &control,
                        &account,
                    )
                    .unwrap();
                    let scope = provider.open(bounds, &control).unwrap();
                    let catalog = Catalog::new(
                        &scope,
                        &compiled.expression,
                        &prepared,
                        options,
                        compiled.options.no_step_subquery_interval_ms,
                        &control,
                        &account,
                    )
                    .unwrap();
                    let rosters = compiled
                        .prepare_rosters(
                            &catalog,
                            &prepared,
                            bounds,
                            &control,
                            &account,
                            &mut Annotations::default(),
                        )
                        .unwrap();
                    let pair = nested.then(|| {
                        (0..compiled.expression.arena.nodes.len())
                            .find_map(|index| {
                                compiled
                                    .nested_grouped_interval_child(
                                        NodeId(index),
                                        &prepared,
                                        &control,
                                        &account,
                                    )
                                    .unwrap()
                                    .and_then(|inner| {
                                        rosters.group_replay(NodeId(index)).map(|outer| {
                                            (outer, rosters.group_replay(inner).unwrap())
                                        })
                                    })
                            })
                            .unwrap()
                    });
                    let plan = pair.map(|pair| pair.0).unwrap_or_else(|| {
                        (0..compiled.expression.arena.nodes.len())
                            .find_map(|index| rosters.group_replay(NodeId(index)))
                            .unwrap()
                    });
                    if let Some((_, inner)) = pair {
                        assert!(inner.supports_interval() && !inner.has_interval());
                    }
                    assert!(plan.supports_interval());
                    assert!(!plan.has_interval());
                    let mut machine = Machine::new(
                        &catalog,
                        &compiled.expression,
                        compiled.expression.root,
                        options,
                        &control,
                        &account,
                        EvaluationMetadata {
                            prepared: &prepared,
                            rosters: &rosters,
                            timestamp_selectors: &compiled.timestamp_selectors,
                            data_bounds: bounds,
                            annotations: None,
                            binary_preparation: None,
                            histogram_preparation: None,
                            info_preparation: None,
                            count_preparation: None,
                        },
                    );
                    let mut rows = 0;
                    if fault {
                        assert!(matches!(machine.next(),
                            Err(EvaluationError::Storage(StorageError::Provider(bytes)))
                                if &*bytes == b"injected page failure"));
                        assert!(!plan.has_completion() && !plan.has_interval());
                        if let Some((_, inner)) = pair {
                            assert!(!inner.has_completion() && !inner.has_interval());
                        }
                    }
                    while !fault && machine.next().unwrap().is_some() {
                        rows += 1;
                        if cancel {
                            control.cancellation.cancel();
                            assert!(matches!(
                                machine.next(),
                                Err(EvaluationError::Interrupted(
                                    crate::storage::Interrupted::Cancelled
                                ))
                            ));
                            break;
                        }
                    }
                    assert_eq!(
                        rows,
                        if fault {
                            0
                        } else if cancel {
                            1
                        } else {
                            2
                        }
                    );
                    let inspection = Control::default();
                    let subquery = compiled
                        .expression
                        .arena
                        .nodes
                        .iter()
                        .position(|node| matches!(node.expression, Expr::Subquery { .. }))
                        .unwrap();
                    let grid = prepared
                        .subquery_scope(NodeId(subquery), &inspection, &account)
                        .unwrap();
                    assert_eq!(grid.end_ms, 8000);
                    let group_node = (0..compiled.expression.arena.nodes.len())
                        .map(NodeId)
                        .find(|node| {
                            rosters
                                .group_replay(*node)
                                .is_some_and(|candidate| std::ptr::eq(candidate, plan))
                        })
                        .unwrap();
                    for index in 0..grid.steps().unwrap() {
                        let time_ms = grid.start_ms + index * grid.interval_ms;
                        let key = crate::vector_matching::ReplayKey::new(
                            compiled.evaluation_options(grid.header(header), time_ms, &prepared),
                            index,
                            prepared.lookback_ns(compiled.options.lookback_ms),
                            bounds,
                        );
                        assert_eq!(
                            plan.interval_contains(key),
                            !fault && time_ms < grid.end_ms,
                            "only actual child completion earns clock {time_ms}"
                        );
                        if !nested && wrapper.is_none() && time_ms == grid.end_ms {
                            let mut completed = 0;
                            for ordinal in 0..rosters.groups(group_node).unwrap().len() {
                                let cell = catalog
                                    .with_computed_group(
                                        group_node,
                                        &inspection,
                                        &account,
                                        |store| {
                                            store.read(key, time_ms, ordinal, &inspection, &account)
                                        },
                                    )
                                    .unwrap()
                                    .expect("computed grouped backing");
                                match cell {
                                    crate::computed_groups::Cell::Present(_) => completed += 1,
                                    crate::computed_groups::Cell::Unknown => (),
                                    crate::computed_groups::Cell::Absent => {
                                        panic!("fixture group is present")
                                    }
                                }
                            }
                            assert_eq!(
                                completed > 0,
                                !fault,
                                "completed values survive final-clock frame retirement"
                            );
                            assert!(
                                !plan.interval_contains(key),
                                "value publication grants no interval certificate"
                            );
                        }
                        if let Some((_, inner)) = pair {
                            assert_eq!(
                                inner.interval_contains(key),
                                !fault,
                                "inner completed clock {time_ms}"
                            );
                        }
                    }
                    drop(machine);
                    rosters
                        .clear_replay_progress(&inspection, &account)
                        .unwrap();
                    assert!(!plan.has_interval() && !plan.has_completion());
                    if let Some((_, inner)) = pair {
                        assert!(!inner.has_interval() && !inner.has_completion());
                    }
                }
                provider.assert_closed();
                drop((account, compiled));
                engine.accounting.snapshot().assert_memory_released();
            }
        }
    }

    #[test]
    fn derived_binary_completed_clocks_preserve_results_and_bounded_reads() {
        for page in [1, 17, 1024] {
            for count in [4, 16] {
                for (expression, multiplier) in [
                    ("max_over_time((m/n)[8s:1s])", 1.0),
                    ("max_over_time((((m/n)))[8s:1s])", 1.0),
                    ("abs(max_over_time((m/n)[8s:1s]))", 1.0),
                    ("sum_over_time((m/n)[8s:1s])", 8.0),
                    ("max_over_time((m/n)[8s:1s] @ 16)", 1.0),
                    ("max_over_time((m/n)[8s:1s] offset 1s)", 1.0),
                ] {
                    let engine = Engine::default();
                    let control = Control::default();
                    let query = engine
                        .compile(expression.as_bytes(), EngineOptions::default(), &control)
                        .unwrap();
                    let mut provider = ordered_binary_provider(page, count);
                    for series in &mut provider.series {
                        series.source.count = 16;
                    }
                    let report = query.collect_reported(
                        &provider,
                        QueryRequest::Instant { time_ms: 16000 },
                        &control,
                    );
                    let result = report.result.as_ref().unwrap();
                    assert!(report.annotations.is_empty());
                    assert_eq!(result.series.len(), count);
                    for (identity, row) in result.series.iter().enumerate() {
                        let id = format!("{identity:06}");
                        assert_eq!(
                            row.labels
                                .0
                                .iter()
                                .map(|label| (&*label.name, &*label.value))
                                .collect::<Vec<_>>(),
                            [
                                (b"id".as_slice(), id.as_bytes()),
                                (b"job".as_slice(), b"worker".as_slice())
                            ]
                        );
                        assert_eq!(row.points.len(), 1);
                        assert_eq!(row.points[0].time_ms, 16000);
                        let value: f64 = if identity.is_multiple_of(2) { 0.5 } else { 2.0 };
                        assert_eq!(float_bits(&row.points[0]), (value * multiplier).to_bits());
                    }
                    assert_eq!(report.observations.output_samples, count as u64);
                    assert_eq!(
                        report
                            .observations
                            .statistics
                            .samples
                            .total_queryable_samples,
                        // The range function consumes eight derived values per series.
                        (8 * count) as u64
                    );
                    assert_eq!(
                        report.observations.memory[MemoryKind::Workspace as usize].current,
                        0
                    );
                    assert!(
                        provider.series.iter().all(|row| row
                            .source
                            .counters
                            .peak
                            .load(Ordering::Relaxed)
                            == 1)
                    );
                    println!(
                        "derived-binary-clocks expression={expression:?} page={page} count={count} fetched={} work={}",
                        report.observations.samples_fetched, report.observations.work
                    );
                    if count == 16 && page == 17 && expression == "max_over_time((m/n)[8s:1s])" {
                        // The complete result must pass before detecting the repeated full-discovery regression.
                        assert!(report.observations.samples_fetched < 100_000);
                    }
                    provider.assert_closed();
                    drop((report, query));
                    engine.accounting.snapshot().assert_memory_released();
                }
            }
        }
    }

    #[test]
    fn derived_binary_completed_clocks_preserve_required_read_failures() {
        let request = QueryRequest::Instant { time_ms: 3000 };
        for page in [1, 17, 1024] {
            let engine = Engine::default();
            let control = Control::default();
            let query = engine
                .compile(
                    b"max_over_time((m/n)[2s:1s])",
                    EngineOptions::default(),
                    &control,
                )
                .unwrap();
            let calibration = ordered_binary_provider(page, 2);
            let (rows, prepared, plans) =
                float_map_join_preparation_with_discovery(&query, &calibration, request, &control);
            assert_eq!((rows, plans), (2, 1));
            let provider = ordered_binary_provider(page, 2);
            let mut sink = RecordingSink::default();
            let report = query.execute_reported(&provider, request, &control, &mut sink);
            assert!(report.result.is_ok());
            assert!(sink.begun && sink.committed && !sink.aborted);
            provider.assert_closed();
            let last = provider
                .series
                .iter()
                .map(|series| series.source.counters.opened.load(Ordering::Relaxed))
                .collect::<Vec<_>>();
            drop(report);
            let mut faults = 0;
            for (position, (&first, &last)) in prepared.iter().zip(&last).enumerate() {
                assert!(last > first);
                for acquisition in first + 1..=last {
                    let mut provider = ordered_binary_provider(page, 2);
                    provider.series[position].source.fail_acquisition = Some(acquisition);
                    let mut sink = RecordingSink::default();
                    let report = query.execute_reported(&provider, request, &control, &mut sink);
                    assert!(
                        matches!(&report.result, Err(ExecutionError::Evaluation(EvaluationError::Storage(StorageError::Provider(bytes)))) if &**bytes == b"injected page failure")
                    );
                    assert!(sink.begun && sink.aborted && !sink.committed);
                    assert_eq!(
                        provider.series[position]
                            .source
                            .counters
                            .opened
                            .load(Ordering::Relaxed),
                        acquisition
                    );
                    assert!(report.annotations.is_empty());
                    report.assert_retained_callback_error_memory();
                    provider.assert_closed();
                    faults += 1;
                }
            }
            println!("derived-binary-clocks page={page} post-preparation-faults={faults}");
            drop(query);
            engine.accounting.snapshot().assert_memory_released();
        }
    }

    #[test]
    fn ordered_binary_consumers_check_complete_results_before_bounded_reads() {
        let mut growth = Vec::new();
        let mut complete = 0;
        for (expression, grouped) in [
            ("m+n", false),
            ("m>n", false),
            ("m>bool n", false),
            ("abs(m+n)", false),
            ("sum by(job)(m+n)", true),
        ] {
            for delayed in [false, true] {
                for page in [17, 1024] {
                    for count in [2, 4, 8, 16] {
                        let engine = Engine::default();
                        let control = Control::default();
                        let provider = ordered_binary_provider(page, count);
                        let query = engine
                            .compile(
                                expression.as_bytes(),
                                EngineOptions {
                                    delayed_name_removal: delayed,
                                    ..EngineOptions::default()
                                },
                                &control,
                            )
                            .unwrap();
                        let (report, ordinal_hits) =
                            crate::vector_matching::observe_frozen_ordinal_hits(|| {
                                query.collect_reported(
                                    &provider,
                                    QueryRequest::Range {
                                        start_ms: 1000,
                                        end_ms: 3000,
                                        step_ms: 1000,
                                    },
                                    &control,
                                )
                            });
                        assert_eq!(
                            ordinal_hits > 0,
                            expression == "sum by(job)(m+n)"
                                || expression == "abs(m+n)" && !delayed
                        );
                        eprintln!(
                            "frozen ordinal hits: {expression:?} delayed={delayed} count={count} page={page} hits={ordinal_hits}"
                        );
                        let result = report.result.as_ref().unwrap();
                        assert!(report.annotations.is_empty());
                        let filtered = expression == "m>n";
                        let boolean = expression == "m>bool n";
                        let rows = if grouped {
                            1
                        } else if filtered {
                            count / 2
                        } else {
                            count
                        };
                        assert_eq!(result.series.len(), rows);
                        for (position, row) in result.series.iter().enumerate() {
                            let identity = if filtered { position * 2 + 1 } else { position };
                            let labels: Vec<_> = row
                                .labels
                                .0
                                .iter()
                                .map(|label| (&*label.name, &*label.value))
                                .collect();
                            let identity_label = format!("{identity:06}");
                            if grouped {
                                assert_eq!(labels, [(b"job".as_slice(), b"worker".as_slice())]);
                            } else {
                                let mut expected = Vec::new();
                                if filtered {
                                    expected.push((b"__name__".as_slice(), b"m".as_slice()));
                                }
                                expected.extend([
                                    (b"id".as_slice(), identity_label.as_bytes()),
                                    (b"job".as_slice(), b"worker".as_slice()),
                                ]);
                                assert_eq!(labels, expected);
                            }
                            assert_eq!(row.points.len(), 3);
                            let slope = if grouped {
                                (count.div_ceil(2) * 6 + count / 2 * 12) as f64
                            } else if filtered {
                                8.0
                            } else if identity.is_multiple_of(2) {
                                6.0
                            } else {
                                12.0
                            };
                            for (tick, point) in row.points.iter().enumerate() {
                                assert_eq!(point.time_ms, (tick as i64 + 1) * 1000);
                                let value = if boolean {
                                    (identity % 2) as f64
                                } else {
                                    slope * (tick + 1) as f64
                                };
                                assert_eq!(float_bits(point), value.to_bits());
                            }
                        }
                        assert_eq!(report.observations.output_samples, 3 * rows as u64);
                        let fetched: usize = provider
                            .series
                            .iter()
                            .map(|row| row.source.counters.samples_returned.load(Ordering::Relaxed))
                            .sum();
                        assert_eq!(report.observations.samples_fetched, fetched as u64);
                        assert!(
                            provider.series.iter().all(|row| {
                                row.source.counters.peak.load(Ordering::Relaxed) == 1
                            })
                        );
                        assert_eq!(
                            report.observations.memory[MemoryKind::Workspace as usize].current,
                            0
                        );
                        println!(
                            "ordered-binary-growth expression={expression:?} delayed={delayed} rows={count} page={page} fetched={} work={}",
                            report.observations.samples_fetched, report.observations.work
                        );
                        if !delayed
                            || matches!(expression, "m+n" | "m>n" | "m>bool n" | "sum by(job)(m+n)")
                        {
                            growth.push((
                                report.observations.samples_fetched,
                                report.observations.work,
                            ));
                        }
                        provider.assert_closed();
                        drop((report, query));
                        engine.accounting.snapshot().assert_memory_released();
                        complete += 1;
                    }
                }
            }
        }
        assert_eq!(complete, 80);
        eprintln!("completed ordered binary controls: {complete}");
        assert!(
            growth
                .chunks_exact(4)
                .all(|rows| { rows[3].0 <= rows[1].0 * 6 && rows[3].1 <= rows[1].1 * 8 }),
            "ordered binary consumers must avoid repeated all-row reads: {growth:?}"
        );
    }

    #[test]
    fn root_delayed_join_preserves_actual_matrix_failure_phases() {
        let acquisitions = |provider: &FixtureProvider| {
            provider
                .series
                .iter()
                .map(|row| row.source.counters.opened.load(Ordering::Relaxed))
                .collect::<Vec<_>>()
        };
        for page in [1, 17, 1024] {
            let engine = Engine::default();
            let compiled = engine
                .compile(
                    b"m+n",
                    EngineOptions {
                        delayed_name_removal: true,
                        ..EngineOptions::default()
                    },
                    &Control::default(),
                )
                .unwrap();
            let mut landmarks: Vec<Vec<usize>> = Vec::new();
            let (mut selected, mut excluded) = (0, 0);
            for fault in ["none", "cold", "suffix", "warm", "next", "cancel"] {
                let control = Control::default();
                let mut provider = ordered_binary_provider(page, 4);
                // Ascending physical pairs leave a genuine unvisited suffix after the first output.
                for side in provider.series.chunks_mut(4) {
                    side.reverse();
                }
                let failed_at = match fault {
                    "cold" => Some((0, 0)),
                    "suffix" | "warm" | "cancel" => Some((0, 1)),
                    "next" => Some((1, 0)),
                    _ => None,
                };
                if fault != "none" && fault != "cancel" {
                    let (target, acquisition) = match fault {
                        "cold" => (excluded, landmarks[0][excluded] + 1),
                        "suffix" => (excluded, landmarks[1][excluded] + 1),
                        "warm" => (selected, landmarks[2][selected]),
                        "next" => (excluded, landmarks[3][excluded] + 1),
                        _ => unreachable!(),
                    };
                    provider.series[target].source.fail_acquisition = Some(acquisition);
                }
                let account = compiled.execution_accounting();
                {
                    let shape_header = compiled
                        .header(QueryRequest::Range {
                            start_ms: 1000,
                            end_ms: 3000,
                            step_ms: 1000,
                        })
                        .unwrap();
                    let prepared = Prepared::new(
                        &compiled.expression,
                        &compiled.preprocessing,
                        shape_header,
                        compiled.options.no_step_subquery_interval_ms,
                        &control,
                        &account,
                    )
                    .unwrap();
                    let header = prepared.evaluator_header();
                    prepared.activate(header, &control, &account).unwrap();
                    let initial = compiled.evaluation_options(header, 1000, &prepared);
                    let bounds = crate::query_bounds::find(
                        &compiled.expression,
                        initial,
                        &prepared,
                        &control,
                        &account,
                    )
                    .unwrap();
                    let scope = provider.open(bounds, &control).unwrap();
                    let catalog = Catalog::new(
                        &scope,
                        &compiled.expression,
                        &prepared,
                        initial,
                        compiled.options.no_step_subquery_interval_ms,
                        &control,
                        &account,
                    )
                    .unwrap();
                    let mut rosters = compiled
                        .prepare_rosters(
                            &catalog,
                            &prepared,
                            bounds,
                            &control,
                            &account,
                            &mut Annotations::default(),
                        )
                        .unwrap();
                    let root = compiled.expression.root;
                    assert!(!rosters.binary(root).unwrap().has_pair_discovery());
                    compiled
                        .certify_pair_replay(
                            root,
                            shape_header,
                            header,
                            false,
                            false,
                            &prepared,
                            &mut rosters,
                            &control,
                            &account,
                        )
                        .unwrap();
                    if fault == "none" {
                        landmarks.push(acquisitions(&provider));
                    } else {
                        assert_eq!(acquisitions(&provider), landmarks[0]);
                    }
                    'clocks: for clock in 0..2 {
                        let time = (clock + 1) * 1000;
                        let options = compiled.evaluation_options(header, time, &prepared);
                        let key = crate::vector_matching::ReplayKey::new(
                            options,
                            clock,
                            prepared.lookback_ns(options.lookback_ms),
                            bounds,
                        );
                        let plan = rosters.binary(root).unwrap();
                        assert!(!plan.has_completed_pair_replay(&key));
                        let mut machine = Machine::new(
                            &catalog,
                            &compiled.expression,
                            root,
                            options,
                            &control,
                            &account,
                            EvaluationMetadata {
                                prepared: &prepared,
                                rosters: &rosters,
                                timestamp_selectors: &compiled.timestamp_selectors,
                                data_bounds: bounds,
                                annotations: None,
                                binary_preparation: None,
                                histogram_preparation: None,
                                info_preparation: None,
                                count_preparation: None,
                            },
                        );
                        machine.set_step_index(clock);
                        for position in 0..4 {
                            let before = acquisitions(&provider);
                            if fault == "cancel" && (clock, position) == (0, 1) {
                                control.cancellation.cancel();
                            }
                            let result = machine.next();
                            if failed_at == Some((clock, position)) {
                                if fault == "cancel" {
                                    assert!(matches!(
                                        result,
                                        Err(EvaluationError::Interrupted(Interrupted::Cancelled))
                                    ));
                                    assert_eq!(acquisitions(&provider), before);
                                } else {
                                    assert!(
                                        matches!(&result, Err(EvaluationError::Storage(StorageError::Provider(bytes)))
                                        if &**bytes == b"injected page failure"),
                                        "{fault} {clock}:{position}"
                                    );
                                }
                                drop(result);
                                assert_eq!(plan.has_completed_pair_replay(&key), fault == "warm");
                                break 'clocks;
                            }
                            let sample = result.unwrap().unwrap();
                            let identity = sample
                                .labels
                                .0
                                .iter()
                                .find(|label| &*label.name == b"id")
                                .unwrap();
                            assert_eq!(&*identity.value, format!("{position:06}").as_bytes());
                            let descriptor = &rosters.descriptors(root)[position];
                            assert_eq!(sample.ordinal, descriptor.ordinal);
                            assert_eq!(sample.drop_name, descriptor.drop_name);
                            assert!(
                                crate::binary_labels::same(
                                    &sample.labels,
                                    &descriptor.labels,
                                    &control,
                                    &account
                                )
                                .unwrap()
                            );
                            let OwnedValue::Float(value) = sample.value else {
                                panic!("float join");
                            };
                            let expected = (if position.is_multiple_of(2) {
                                6.0
                            } else {
                                12.0
                            }) * (clock + 1) as f64;
                            assert_eq!(value.to_bits(), expected.to_bits());
                            assert_eq!(plan.has_completed_pair_replay(&key), position != 0);
                            if fault == "none" && clock == 0 && position < 2 {
                                landmarks.push(acquisitions(&provider));
                            }
                        }
                        assert!(machine.next().unwrap().is_none());
                        assert!(plan.has_completed_pair_replay(&key));
                        if fault == "none" && clock == 0 {
                            landmarks.push(acquisitions(&provider));
                        }
                    }
                }
                provider.assert_closed();
                account.snapshot().assert_memory_released();
                drop(account);
                if fault == "none" {
                    selected = provider
                        .series
                        .iter()
                        .position(|row| {
                            row.labels
                                .iter()
                                .any(|(name, value)| name == b"id" && value == b"000001")
                        })
                        .unwrap();
                    excluded = provider
                        .series
                        .iter()
                        .position(|row| {
                            row.labels
                                .iter()
                                .any(|(name, value)| name == b"id" && value == b"000002")
                        })
                        .unwrap();
                    assert_eq!(landmarks.len(), 4);
                    assert_eq!(landmarks[1][excluded], landmarks[0][excluded] + 1);
                    assert_eq!(landmarks[2][excluded], landmarks[1][excluded] + 1);
                    assert_eq!(landmarks[2][selected], landmarks[1][selected] + 2);
                    assert_eq!(landmarks[3][excluded], landmarks[2][excluded] + 1);
                    eprintln!("root Matrix acquisition phases page={page}: {landmarks:?}");
                }
            }
            drop(compiled);
            engine.accounting.snapshot().assert_memory_released();
        }
    }

    #[test]
    fn root_delayed_join_keeps_simultaneous_and_disjoint_name_aliases() {
        fn disjoint<const LEFT: bool>(index: usize) -> crate::value::Sample {
            crate::value::Sample {
                time_ms: (index as i64 + 1) * 1000,
                start_time_ms: 0,
                value: crate::value::SampleValue::Float(if (index != 1) == LEFT {
                    (index + 1) as f64
                } else {
                    f64::from_bits(crate::value::STALE_NAN_BITS)
                }),
            }
        }
        let expression = b"{__name__=~\"m|n\"} == bool on(__name__,id,job) {__name__=~\"m|n\"}";
        for page in [1, 17, 1024] {
            for delayed in [false, true] {
                for separate in [false, true] {
                    let engine = Engine::default();
                    let control = Control::default();
                    let mut provider = ordered_binary_provider(page, 2);
                    if separate {
                        for (index, row) in provider.series.iter_mut().enumerate() {
                            row.source.sample = if index < 2 {
                                disjoint::<true>
                            } else {
                                disjoint::<false>
                            };
                        }
                    }
                    let compiled = engine
                        .compile(expression, options(delayed), &control)
                        .unwrap();
                    let report = compiled.collect_reported(
                        &provider,
                        QueryRequest::Range {
                            start_ms: 1000,
                            end_ms: 3000,
                            step_ms: 1000,
                        },
                        &control,
                    );
                    assert!(report.annotations.is_empty());
                    if separate {
                        let result = report.result.as_ref().unwrap();
                        assert_eq!(result.series.len(), 2);
                        for (index, row) in result.series.iter().enumerate() {
                            let labels: Vec<_> = row
                                .labels
                                .0
                                .iter()
                                .map(|label| (&*label.name, &*label.value))
                                .collect();
                            let identity = format!("{index:06}");
                            assert_eq!(
                                labels,
                                [(b"id".as_slice(), identity.as_bytes()), (b"job", b"worker")]
                            );
                            assert_eq!(row.points.len(), 3);
                            for (tick, point) in row.points.iter().enumerate() {
                                assert_eq!(point.time_ms, (tick as i64 + 1) * 1000);
                                assert_eq!(float_bits(point), 1.0f64.to_bits());
                            }
                        }
                        assert_eq!(report.observations.output_samples, 6);
                    } else {
                        assert!(is_duplicate(report.result.as_ref().unwrap_err()));
                    }
                    assert_eq!(
                        report.observations.memory[MemoryKind::Workspace as usize].current,
                        0
                    );
                    provider.assert_closed();
                    drop((report, compiled));
                    engine.accounting.snapshot().assert_memory_released();
                }
            }
        }
    }

    #[test]
    fn ordered_binary_preparation_preserves_local_and_fallback_boundaries() {
        let range = QueryRequest::Range {
            start_ms: 1000,
            end_ms: 3000,
            step_ms: 1000,
        };
        for page in [1, 17, 1024] {
            for count in [0, 1, 4] {
                for (expression, supported) in [
                    ("sum by(job)(m+n)", true),
                    ("sum by(job)(m @ 2+n)", false),
                    ("sum by(job)(sum by(id)(m)+sum by(id)(n))", true),
                ] {
                    for (request, ranged) in [
                        (range, true),
                        (QueryRequest::Instant { time_ms: 2000 }, false),
                        (
                            QueryRequest::Range {
                                start_ms: 2000,
                                end_ms: 2000,
                                step_ms: 1000,
                            },
                            false,
                        ),
                    ] {
                        for delayed in [false, true] {
                            let engine = Engine::default();
                            let control = Control::default();
                            let compiled = engine
                                .compile(expression.as_bytes(), options(delayed), &control)
                                .unwrap();
                            let provider = ordered_binary_provider(page, count);
                            let (rows, _, plans) = float_map_join_preparation_with_discovery(
                                &compiled, &provider, request, &control,
                            );
                            assert_eq!(rows, usize::from(count != 0));
                            assert_eq!(
                                plans,
                                usize::from(
                                    supported
                                        && ranged
                                        && count > 1
                                        && (!delayed || expression == "sum by(job)(m+n)")
                                ),
                                "{expression} {request:?} count{count} delayed{delayed}"
                            );
                            drop(compiled);
                            engine.accounting.snapshot().assert_memory_released();
                        }
                    }
                }
            }
            let engine = Engine::default();
            let control = Control::default();
            let compiled = engine
                .compile(b"sum by(job)(m+n)", options(false), &control)
                .unwrap();
            let mut provider = ordered_binary_provider(page, 4);
            provider.series[0].source.sample = |index| crate::value::Sample {
                time_ms: (index as i64 + 1) * 1000,
                start_time_ms: 0,
                value: crate::value::SampleValue::FloatHistogram(
                    crate::histogram::FloatHistogram {
                        count: 1.0,
                        sum: 1.0,
                        zero_count: 1.0,
                        zero_threshold: 1.0,
                        ..crate::histogram::FloatHistogram::default()
                    },
                ),
            };
            let (_, _, plans) =
                float_map_join_preparation_with_discovery(&compiled, &provider, range, &control);
            assert_eq!(plans, 0, "mixed raw operands must retain fallback");
            drop(compiled);
            engine.accounting.snapshot().assert_memory_released();
        }
    }

