    #[test]
    fn window_set_discovery_admission() {
        let mut bodies = Vec::new();
        for function in [
            "rate",
            "increase",
            "delta",
            "irate",
            "idelta",
            "count_over_time",
            "present_over_time",
            "first_over_time",
            "last_over_time",
            "min_over_time",
            "max_over_time",
            "sum_over_time",
            "avg_over_time",
            "stdvar_over_time",
            "stddev_over_time",
            "ts_of_first_over_time",
            "ts_of_last_over_time",
            "ts_of_min_over_time",
            "ts_of_max_over_time",
            "changes",
            "resets",
        ] {
            let call = format!("{function}(counter_total[2s])");
            bodies.push((call.clone(), true));
            bodies.push((format!("0 < bool (({call}))"), true));
        }
        for (body, admitted) in [
            ("rate(counter_total[2s] offset 1s)", true),
            ("rate(counter_total[2s] @ 3)", false),
            ("rate(counter_total[2s] anchored)", false),
            ("rate(counter_total[2s] smoothed)", false),
            ("rate(counter_total[2s:1s])", false),
            ("absent_over_time(counter_total[2s])", false),
            ("deriv(counter_total[2s])", false),
            ("quantile_over_time(0.5,counter_total[2s])", false),
            ("rate(counter_total[2s]) > scalar(vector(0))", false),
            ("abs(rate(counter_total[2s]))", false),
            ("rate(counter_total[2s]) + 1", false),
            ("(rate(counter_total[2s]) > 0) > 0", false),
            (
                "label_join(rate(counter_total[2s]),\"branch\",\"\",\"instance\")",
                false,
            ),
            (
                "label_join(rate(counter_total[2s]) > 0,\"branch\",\"\",\"instance\")",
                false,
            ),
        ] {
            bodies.push((body.to_string(), admitted));
        }
        for (body, admitted) in bodies {
            for (request, multiple) in [
                (QueryRequest::Instant { time_ms: 4000 }, false),
                (
                    QueryRequest::Range {
                        start_ms: 4000,
                        end_ms: 4000,
                        step_ms: 1000,
                    },
                    false,
                ),
                (
                    QueryRequest::Range {
                        start_ms: 4000,
                        end_ms: 4001,
                        step_ms: 1000,
                    },
                    false,
                ),
                (
                    QueryRequest::Range {
                        start_ms: 2000,
                        end_ms: 4000,
                        step_ms: 1000,
                    },
                    true,
                ),
            ] {
                for delayed in [false, true] {
                    let engine = Engine::default();
                    let control = Control::default();
                    let mut options = options(delayed);
                    options.parser.experimental_functions = true;
                    options.parser.extended_range_selectors = true;
                    let expression = format!("({body}) and on(instance) counter_total");
                    let compiled = engine
                        .compile(expression.as_bytes(), options, &control)
                        .unwrap();
                    let provider = FixtureProvider::new(4, 1, 4);
                    assert_eq!(
                        prepared_set_discovery_count(&compiled, &provider, request, &control),
                        usize::from(admitted && multiple),
                        "{body} {request:?} delayed={delayed}"
                    );
                    drop(compiled);
                    engine.accounting.snapshot().assert_memory_released();
                }
            }
        }
    }

    fn comparison_set_provider(page: usize) -> FixtureProvider {
        let mut provider = FixtureProvider::new(5, page, 8);
        provider.filter_selectors = true;
        for (index, series) in provider.series.iter_mut().enumerate() {
            series.labels[0].1 = if index < 4 { b"m_total" } else { b"n_total" }.to_vec();
            series.labels[1].1 = (index % 4).to_string().into_bytes();
            series.source.counters = Default::default();
            if index < 4 {
                series.source.sample = |index| {
                    let mut sample = crate::test_storage::counter(index);
                    sample.value =
                        crate::value::SampleValue::Float(if index % 2 == 0 { 1.0 } else { -1.0 });
                    sample
                };
            }
        }
        provider
    }

    #[test]
    fn comparison_set_discovery_preserves_filtered_and_bool_values() {
        for page in [1, 17, 1024] {
            for (expression, boolean) in [
                ("(m_total > 0) and on(instance) n_total", false),
                ("(m_total > bool 0) and on(instance) n_total", true),
                ("(0 < m_total) unless on(instance) (n_total < 0)", false),
                ("(0 < bool m_total) or on(instance) (n_total < 0)", true),
            ] {
                let engine = Engine::default();
                let control = Control::default();
                let query = engine
                    .compile(expression.as_bytes(), EngineOptions::default(), &control)
                    .unwrap();
                let provider = comparison_set_provider(page);
                let report = query.collect_reported(
                    &provider,
                    QueryRequest::Range {
                        start_ms: 1000,
                        end_ms: 5000,
                        step_ms: 1000,
                    },
                    &control,
                );
                let result = report.result.as_ref().unwrap();
                assert!(report.annotations.is_empty());
                assert_eq!(result.series.len(), 4);
                for (index, row) in result.series.iter().enumerate() {
                    let identity = index.to_string();
                    let mut expected = vec![
                        (b"instance".as_slice(), identity.as_bytes()),
                        (b"job".as_slice(), b"worker".as_slice()),
                    ];
                    if !boolean {
                        expected.insert(0, (b"__name__".as_slice(), b"m_total".as_slice()));
                    }
                    assert_eq!(
                        row.labels
                            .0
                            .iter()
                            .map(|label| (&*label.name, &*label.value))
                            .collect::<Vec<_>>(),
                        expected
                    );
                    let ticks: &[i64] = if boolean {
                        &[1, 2, 3, 4, 5]
                    } else {
                        &[1, 3, 5]
                    };
                    assert_eq!(row.points.len(), ticks.len());
                    for (point, tick) in row.points.iter().zip(ticks) {
                        assert_eq!(point.time_ms, tick * 1000);
                        assert_eq!(
                            float_bits(point),
                            if tick % 2 == 0 { 0_f64 } else { 1_f64 }.to_bits()
                        );
                    }
                }
                provider.assert_closed();
                drop((report, query));
                engine.accounting.snapshot().assert_memory_released();
            }
        }
    }

