    #[test]
    fn nested_selection_reuses_ready_parameters_without_the_known_cardinality_factor() {
        fn one(_: usize) -> crate::value::Sample {
            crate::value::Sample {
                time_ms: 1000,
                start_time_ms: 0,
                value: crate::value::SampleValue::Float(1.0),
            }
        }
        for operator in ["topk", "bottomk", "limitk", "limit_ratio"] {
            let mut reads = Vec::new();
            for depth in [1, 4] {
                let mut provider = FixtureProvider::new(1, 1, 24);
                for series in &mut provider.series {
                    series.source.sample = one;
                }
                let engine = Engine::default();
                let control = Control::default();
                let parameter = if operator == "limit_ratio" { "-1" } else { "5" };
                let mut source = format!("{operator}({parameter},counter_total)");
                for _ in 0..depth {
                    source = if operator == "limit_ratio" {
                        format!("{operator}(-scalar(sum({source}))/24,counter_total)")
                    } else {
                        format!("{operator}(scalar(sum({source})),counter_total)")
                    };
                }
                let mut settings = EngineOptions::default();
                settings.parser.experimental_functions = true;
                let query = engine
                    .compile(source.as_bytes(), settings, &control)
                    .unwrap();
                let (result, observed) = query
                    .collect(&provider, QueryRequest::Instant { time_ms: 1000 }, &control)
                    .unwrap();
                assert_eq!(
                    result.series.len(),
                    if operator == "limit_ratio" { 24 } else { 5 }
                );
                assert!(
                    result
                        .series
                        .iter()
                        .all(|row| float_bits(&row.points[0]) == 1.0_f64.to_bits())
                );
                reads.push(observed.samples_fetched);
                provider.assert_closed();
                assert_eq!(
                    provider.series[0]
                        .source
                        .counters
                        .peak
                        .load(Ordering::Relaxed),
                    1
                );
                drop((result, query));
                engine.accounting.snapshot().assert_memory_released();
            }
            // This producer class rules out its known repeated-parameter factor, not every expression shape.
            assert!(reads[1] < reads[0] * 6, "{operator}: {reads:?}");
        }
    }

    #[test]
    fn histogram_preprocessing_stops_before_enqueuing_cancelled_variadic_arguments() {
        let engine = Engine::default();
        let control = Control::default();
        let mut source = "(".repeat(8191);
        source.push_str("label_join(counter_total,\"destination\",\",\"");
        for _ in 0..10_000 {
            source.push_str(",\"id\"");
        }
        source.push(')');
        source.push_str(&")".repeat(8191));
        let mut query = engine
            .compile(source.as_bytes(), EngineOptions::default(), &control)
            .unwrap();
        let account = engine.accounting.query();
        let result = crate::test_storage::interrupt_during(&account, &control, || {
            crate::histogram_stats::configure(&mut query.expression, &control, &account)
        });
        assert_eq!(result, Err(Interrupted::Cancelled));
        let observed = account.snapshot();
        assert_eq!(observed.work, 8192);
        assert!(
            observed.memory[MemoryKind::Workspace as usize].peak
                < (100 * size_of::<(NodeId, bool, bool)>()) as u64,
            "pending cancellation must precede the variable argument task allocation: {observed:?}"
        );
        drop(query);
        account.snapshot().assert_memory_released();
        drop(account);
        engine.accounting.snapshot().assert_memory_released();
    }

    #[test]
    fn failed_selection_positions_account_work_without_replacing_provider_error() {
        use crate::storage::{
            ProviderDiagnosticRef, ProviderResources, SelectionRequest, SeriesSelection,
        };
        #[derive(Clone, Copy)]
        struct FailedSelection {
            position: usize,
        }
        impl Provider for FailedSelection {
            type Query<'a> = Self;
            fn open(&self, _: TimeBounds, _: &Control) -> Result<Self, StorageError> {
                Ok(*self)
            }
        }
        impl QueryProvider for FailedSelection {
            type Selection<'a> = Self;
            fn resources(&self) -> ProviderResources {
                ProviderResources::default()
            }
            fn select(&self, _: SelectionRequest<'_>, _: &Control) -> Result<Self, StorageError> {
                Ok(*self)
            }
        }
        impl SeriesSelection for FailedSelection {
            type Series = crate::test_storage::FixtureHandle<'static>;
            fn resources(&self) -> ProviderResources {
                ProviderResources::default()
            }
            fn next(&mut self, control: &Control) -> Result<Option<Self::Series>, StorageError> {
                control.cancellation.cancel();
                Err(StorageError::Provider(b"selection failure".to_vec().into()))
            }
            fn diagnostic_count(&self) -> usize {
                1
            }
            fn diagnostic<R>(
                &self,
                _: usize,
                visit: impl for<'a> FnOnce(ProviderDiagnosticRef<'a>) -> R,
            ) -> R {
                visit(ProviderDiagnosticRef {
                    message: b"",
                    severity: crate::annotations::Severity::Info,
                    position: Some(crate::frontend::Span {
                        start: self.position,
                        end: self.position,
                    }),
                })
            }
        }
        let engine = Engine::default();
        let source = format!("{}counter_total", " ".repeat(32_768));
        let query = engine
            .compile(
                source.as_bytes(),
                EngineOptions::default(),
                &Control::default(),
            )
            .unwrap();
        let mut work = Vec::new();
        for position in [0, 32_768] {
            let control = Control::default();
            let account = query.execution_accounting();
            let report = query.collect_reported_in(
                &FailedSelection { position },
                QueryRequest::Instant { time_ms: 0 },
                &control,
                &account,
            );
            assert!(control.cancellation.cancelled());
            let Err(ExecutionError::Evaluation(EvaluationError::Expansion(error))) = &report.result
            else {
                panic!("the completed selection error must precede cancellation")
            };
            assert_eq!(&**error, b"expanding series: selection failure");
            let note = report
                .annotations
                .iter()
                .next()
                .expect("positioned diagnostic");
            assert!(note.raw_message.is_empty());
            assert_eq!(note.message, format!(" (1:{})", position + 1).as_bytes());
            assert_eq!(note.span.unwrap().start, position);
            work.push(report.observations.work);
            drop(report);
            account.snapshot().assert_memory_released();
        }
        assert!(
            work[1] - work[0] >= 32_768,
            "visited prefix bytes must be charged after a completed error: {work:?}"
        );
        drop(query);
        engine.accounting.snapshot().assert_memory_released();
    }

    #[test]
    fn parenthesis_projection_reports_work_and_observes_cancellation() {
        use crate::storage::Interrupted;
        let engine = Engine::default();
        let control = Control::default();
        let source = format!(
            "sum({}counter_total{})",
            "(".repeat(10_000),
            ")".repeat(10_000)
        );
        let query = engine
            .compile(source.as_bytes(), EngineOptions::default(), &control)
            .unwrap();
        let Expr::Aggregate {
            expression: Some(argument),
            ..
        } = query.expression.arena[query.expression.root].expression
        else {
            panic!("aggregate argument");
        };
        let account = engine.accounting.query();
        let before = account.snapshot().work;
        let result = crate::test_storage::interrupt_during(&account, &control, || {
            let child = query.preprocessing.child(
                &query.expression,
                query.expression.root,
                argument,
                &control,
                &account,
            )?;
            control.check()?;
            Ok(child)
        });
        assert_eq!(result, Err(Interrupted::Cancelled));
        assert!(account.snapshot().work - before < 10_000);
        drop(query);
        account.snapshot().assert_memory_released();
        drop(account);
        engine.accounting.snapshot().assert_memory_released();
    }

    #[test]
    fn skipped_variadic_string_children_poll_without_collecting_a_second_task_array() {
        use crate::storage::Interrupted;
        let engine = Engine::default();
        let control = Control::default();
        let mut source = b"sort_by_label(counter_total".to_vec();
        for _ in 0..10_000 {
            source.extend_from_slice(b",\"id\"");
        }
        source.push(b')');
        let query = engine
            .compile(
                &source,
                EngineOptions {
                    parser: ParserOptions {
                        experimental_functions: true,
                        ..ParserOptions::default()
                    },
                    ..options(true)
                },
                &control,
            )
            .unwrap();
        let account = engine.accounting.query();
        let header = query
            .header(QueryRequest::Instant { time_ms: 1000 })
            .unwrap();
        let prepared = Prepared::new(
            &query.expression,
            &query.preprocessing,
            header,
            query.options.no_step_subquery_interval_ms,
            &control,
            &account,
        )
        .unwrap();
        let before = account.snapshot().work;
        let result = crate::test_storage::interrupt_during(&account, &control, || {
            children(
                &query.expression,
                &prepared,
                query.expression.root,
                &control,
                &account,
            )
            .expect("typed child projection")
            .next_back()
        });
        assert!(matches!(result, Some(Err(Interrupted::Cancelled))));
        assert_eq!(account.snapshot().work - before, 8192);
        drop(prepared);
        drop(query);
        account.snapshot().assert_memory_released();
        drop(account);
        engine.accounting.snapshot().assert_memory_released();
    }

    #[test]
    fn cancellation_in_label_callbacks_stops_each_metadata_walk_and_releases_owners() {
        use crate::{storage::Interrupted, test_storage::observe_label_reads};
        const LABELS: usize = 4096;
        for source in [
            &b"counter_total"[..],
            b"counter_total[2s]",
            b"rate(counter_total[2s])",
            b"sum(counter_total)",
            b"scalar(counter_total)",
        ] {
            let mut provider = FixtureProvider::new(2, 1, 1);
            for index in 2..LABELS {
                provider.series[0]
                    .labels
                    .push((format!("z{index:05}").into_bytes(), b"v".to_vec()));
            }
            let engine = Engine::default();
            let control = Control::default();
            let query = engine.compile(source, options(true), &control).unwrap();
            let mut sink = RecordingSink::default();
            let (result, reads) = observe_label_reads(&control, None, || {
                query.execute(
                    &provider,
                    QueryRequest::Instant { time_ms: 2000 },
                    &control,
                    &mut sink,
                )
            });
            result.unwrap();
            assert!(reads >= LABELS);
            provider.assert_closed();
            drop((query, sink));
            engine.accounting.snapshot().assert_memory_released();
            for cancel_at in (2..reads).step_by(provider.series[0].labels.len()) {
                let control = Control::default();
                let query = engine.compile(source, options(true), &control).unwrap();
                let mut sink = RecordingSink::default();
                let (result, observed) = observe_label_reads(&control, Some(cancel_at), || {
                    query.execute(
                        &provider,
                        QueryRequest::Instant { time_ms: 2000 },
                        &control,
                        &mut sink,
                    )
                });
                let error = result.unwrap_err();
                assert!(matches!(
                    error,
                    ExecutionError::Evaluation(EvaluationError::Interrupted(
                        Interrupted::Cancelled
                    )) | ExecutionError::Evaluation(EvaluationError::Storage(
                        StorageError::Interrupted(Interrupted::Cancelled)
                    ))
                ));
                assert!(sink.begun && sink.aborted && !sink.committed);
                provider.assert_closed();
                drop((error, query, sink));
                engine.accounting.snapshot().assert_memory_released();
                assert_eq!(
                    observed,
                    cancel_at,
                    "{}: cancellation callback must end this walk",
                    String::from_utf8_lossy(source)
                );
            }
        }
    }

    #[test]
    fn selection_comparison_cancellation_and_partial_output_release_all_owners() {
        use crate::storage::{Cancellation, Interrupted};
        thread_local! {
            static GATE: std::cell::RefCell<Option<(Cancellation, usize)>> = const { std::cell::RefCell::new(None) };
        }
        fn sample(index: usize) -> crate::value::Sample {
            GATE.with_borrow_mut(|gate| {
                if let Some((cancellation, reads)) = gate {
                    *reads += 1;
                    if *reads == 30 {
                        cancellation.cancel();
                    }
                }
            });
            crate::test_storage::counter(index)
        }
        fn native_sample(index: usize) -> crate::value::Sample {
            let mut point = sample(index);
            point.value =
                crate::value::SampleValue::FloatHistogram(crate::histogram::FloatHistogram {
                    schema: -53,
                    count: 3.0,
                    sum: 5.0,
                    zero_count: 7.0,
                    positive_buckets: Some(vec![1.0, 2.0].into()),
                    custom_values: Some(vec![1.0].into()),
                    ..crate::histogram::FloatHistogram::default()
                });
            point
        }
        for (operator, native) in [
            ("topk", false),
            ("bottomk", false),
            ("limitk", false),
            ("limit_ratio", false),
            ("limitk", true),
            ("limit_ratio", true),
        ] {
            for cancel in [false, true] {
                let mut provider = FixtureProvider::new(1, 1, 8);
                for series in &mut provider.series {
                    series.source.sample = if native { native_sample } else { sample };
                }
                let engine = Engine::default();
                let control = Control::default();
                let parameter = if operator == "limit_ratio" { "-1" } else { "8" };
                let source = format!("{operator}({parameter},counter_total)");
                let mut settings = EngineOptions::default();
                settings.parser.experimental_functions = true;
                let query = engine
                    .compile(source.as_bytes(), settings, &control)
                    .unwrap();
                let mut sink = RecordingSink {
                    fail_after: (!cancel).then_some(2),
                    ..RecordingSink::default()
                };
                if cancel {
                    GATE.with_borrow_mut(|gate| *gate = Some((control.cancellation.clone(), 0)));
                }
                let error = query
                    .execute(
                        &provider,
                        QueryRequest::Instant { time_ms: 1000 },
                        &control,
                        &mut sink,
                    )
                    .unwrap_err();
                if cancel {
                    assert_eq!(GATE.with_borrow_mut(|gate| gate.take().unwrap().1), 30);
                    assert!(matches!(
                        error,
                        ExecutionError::Evaluation(EvaluationError::Interrupted(
                            Interrupted::Cancelled
                        )) | ExecutionError::Evaluation(EvaluationError::Storage(
                            StorageError::Interrupted(Interrupted::Cancelled)
                        ))
                    ));
                } else {
                    assert!(matches!(error, ExecutionError::Sink(_)));
                }
                assert!(sink.begun && sink.aborted && !sink.committed);
                provider.assert_closed();
                drop((error, query, sink));
                engine.accounting.snapshot().assert_memory_released();
            }
        }
    }

    #[test]
    fn info_checks_native_samples_without_a_simultaneous_base_but_skips_empty_step_join_duplicates()
    {
        use crate::{
            histogram::FloatHistogram,
            value::{STALE_NAN_BITS, Sample, SampleValue},
        };
        fn base(index: usize) -> Sample {
            Sample {
                time_ms: (index as i64 + 1) * 1000,
                start_time_ms: 77,
                value: SampleValue::Float(if index == 0 {
                    f64::from_bits(STALE_NAN_BITS)
                } else {
                    42.0
                }),
            }
        }
        fn native_then_float(index: usize) -> Sample {
            Sample {
                time_ms: (index as i64 + 1) * 1000,
                start_time_ms: 0,
                value: if index == 0 {
                    SampleValue::FloatHistogram(FloatHistogram::default())
                } else {
                    SampleValue::Float(1.0)
                },
            }
        }
        for native in [false, true] {
            let mut provider = FixtureProvider::new(2, 1, 3);
            provider.series[0].source.sample = base;
            for (index, series) in provider.series.iter_mut().enumerate().skip(1) {
                series.labels = vec![
                    (b"__name__".to_vec(), b"target_info".to_vec()),
                    (b"data".to_vec(), index.to_string().into_bytes()),
                    (b"instance".to_vec(), b"0".to_vec()),
                    (b"job".to_vec(), b"worker".to_vec()),
                ];
            }
            provider.series[1].source.count = 1;
            if native {
                provider.series[2].source.sample = native_then_float;
            }
            let engine = Engine::default();
            let control = Control::default();
            let mut settings = EngineOptions::default();
            settings.parser.experimental_functions = true;
            let query = engine
                .compile(b"info(counter_total)", settings, &control)
                .unwrap();
            let report = query.collect_reported(
                &provider,
                QueryRequest::Range {
                    start_ms: 1000,
                    end_ms: 2000,
                    step_ms: 1000,
                },
                &control,
            );
            if native {
                assert!(
                    matches!(&report.result, Err(ExecutionError::Evaluation(EvaluationError::Runtime(bytes))) if bytes.starts_with(b"this should be an info metric, with float samples:"))
                );
            } else {
                let output = report.result.as_ref().unwrap();
                assert_eq!(
                    report
                        .observations
                        .statistics
                        .samples
                        .total_queryable_samples,
                    5,
                    "the implicit info selector participates before base/winner filtering",
                );
                assert_eq!(output.series.len(), 1);
                assert_eq!(output.series[0].points.len(), 1);
                assert_eq!(output.series[0].points[0].time_ms, 2000);
                assert_eq!(float_bits(&output.series[0].points[0]), 42.0_f64.to_bits());
                assert!(
                    output.series[0]
                        .labels
                        .0
                        .iter()
                        .any(|label| label.name == b"data" && label.value == b"2")
                );
            }
            provider.assert_closed();
            drop((report, query));
            engine.accounting.snapshot().assert_memory_released();
        }
    }

    fn mapped_group_provider(page: usize, groups: usize) -> FixtureProvider {
        fn counter<const SCALE: u64>(index: usize) -> crate::value::Sample {
            crate::value::Sample {
                time_ms: (index as i64 + 1) * 1000,
                start_time_ms: 0,
                value: crate::value::SampleValue::Float((index as u64 + 1) as f64 * SCALE as f64),
            }
        }
        let mut provider = FixtureProvider::new(5, page, groups * 2);
        for (index, series) in provider.series.iter_mut().enumerate() {
            let group = groups - 1 - index / 2;
            series.labels = vec![
                (b"__name__".to_vec(), b"counter_total".to_vec()),
                (b"instance".to_vec(), format!("g{group:04}").into_bytes()),
                (b"member".to_vec(), (index % 2).to_string().into_bytes()),
            ];
            series.source.sample = if group.is_multiple_of(2) {
                counter::<1>
            } else {
                counter::<2>
            };
            series.source.counters = Default::default();
        }
        provider
    }

    fn native_mapped_group_provider(page: usize, groups: usize) -> FixtureProvider {
        native_group_provider::<false>(page, groups)
    }

    fn native_variance_group_provider(page: usize, groups: usize) -> FixtureProvider {
        native_group_provider::<true>(page, groups)
    }

    fn native_group_provider<const BUCKETS: bool>(page: usize, groups: usize) -> FixtureProvider {
        fn point<const COUNT: u64, const SUM: u64, const BUCKETS: bool>(
            index: usize,
        ) -> crate::value::Sample {
            let time = (index + 1) as f64;
            crate::value::Sample {
                time_ms: (index as i64 + 1) * 1000,
                start_time_ms: 0,
                value: crate::value::SampleValue::FloatHistogram(
                    crate::histogram::FloatHistogram {
                        schema: if BUCKETS {
                            crate::histogram::CUSTOM_BUCKETS_SCHEMA
                        } else {
                            0
                        },
                        zero_threshold: if BUCKETS { 0.0 } else { 128.0 },
                        zero_count: if BUCKETS { 0.0 } else { COUNT as f64 * time },
                        count: COUNT as f64 * time,
                        sum: SUM as f64 * time * time,
                        positive_spans: BUCKETS.then(|| {
                            vec![crate::histogram::Span {
                                offset: 1,
                                length: 1,
                            }]
                            .into()
                        }),
                        positive_buckets: BUCKETS.then(|| vec![COUNT as f64 * time].into()),
                        custom_values: BUCKETS.then(|| vec![1.0, 3.0].into()),
                        ..crate::histogram::FloatHistogram::default()
                    },
                ),
            }
        }
        let mut provider = mapped_group_provider(page, groups);
        for (index, series) in provider.series.iter_mut().enumerate() {
            let group = groups - 1 - index / 2;
            series.source.sample = match (group.is_multiple_of(2), index % 2) {
                (true, 0) => point::<1, 2, BUCKETS>,
                (true, _) => point::<3, 12, BUCKETS>,
                (false, 0) => point::<1, 4, BUCKETS>,
                (false, _) => point::<3, 24, BUCKETS>,
            };
        }
        provider
    }

    fn native_group_field_expected(function: &str, average: bool, group: usize, time: f64) -> f64 {
        let factor = if group.is_multiple_of(2) { 1.0 } else { 2.0 };
        let divisor = if average { 2.0 } else { 1.0 };
        match function {
            "histogram_sum" => factor * 14.0 * time * time / divisor,
            "histogram_count" => 4.0 * time / divisor,
            "histogram_avg" => factor * 3.5 * time,
            "histogram_stdvar" => {
                let distance = 2.0 - factor * 3.5 * time;
                distance * distance
            }
            "histogram_stddev" => (2.0 - factor * 3.5 * time).abs(),
            _ => panic!("unknown native field map"),
        }
    }

    #[test]
    fn native_group_maps_check_complete_results_before_bounded_source_reads() {
        let mut growth = Vec::new();
        for function in [
            "histogram_sum",
            "histogram_count",
            "histogram_avg",
            "histogram_stdvar",
            "histogram_stddev",
        ] {
            for operator in ["sum", "avg"] {
                for delayed in [false, true] {
                    for page in [1, 17, 1024] {
                        for groups in [2_usize, 4, 8, 16] {
                            let variance = function.starts_with("histogram_std");
                            let provider = if variance {
                                native_variance_group_provider(page, groups)
                            } else {
                                native_mapped_group_provider(page, groups)
                            };
                            let engine = Engine::default();
                            let control = Control::default();
                            let expression =
                                format!("{function}({operator} by(instance)(counter_total))");
                            let query = engine
                                .compile(expression.as_bytes(), options(delayed), &control)
                                .unwrap();
                            let report = query.collect_reported(
                                &provider,
                                QueryRequest::Range {
                                    start_ms: 3000,
                                    end_ms: 5000,
                                    step_ms: 1000,
                                },
                                &control,
                            );
                            let result = report.result.as_ref().unwrap();
                            assert!(report.annotations.is_empty());
                            assert_eq!(result.series.len(), groups);
                            for (group, row) in result.series.iter().enumerate() {
                                assert_eq!(row.labels.0.len(), 1);
                                assert_eq!(&*row.labels.0[0].name, b"instance");
                                assert_eq!(
                                    &*row.labels.0[0].value,
                                    format!("g{group:04}").as_bytes()
                                );
                                assert_eq!(row.points.len(), 3);
                                for (tick, point) in row.points.iter().enumerate() {
                                    let time = (tick + 3) as f64;
                                    assert_eq!(point.time_ms, (tick as i64 + 3) * 1000);
                                    assert_eq!(
                                        float_bits(point),
                                        native_group_field_expected(
                                            function,
                                            operator == "avg",
                                            group,
                                            time
                                        )
                                        .to_bits()
                                    );
                                }
                            }
                            assert_eq!(report.observations.output_samples, (3 * groups) as u64);
                            assert_eq!(
                                report
                                    .observations
                                    .statistics
                                    .samples
                                    .total_queryable_samples,
                                (if variance { 78 } else { 66 } * groups) as u64
                            );
                            assert_eq!(
                                report.observations.memory[MemoryKind::Workspace as usize].current,
                                0
                            );
                            provider.assert_closed();
                            println!(
                                "native-group-complete function={function} operator={operator} delayed={delayed} page={page} groups={groups} fetched={} work={}",
                                report.observations.samples_fetched, report.observations.work
                            );
                            growth.push(report.observations.samples_fetched);
                            drop((report, query));
                            engine.accounting.snapshot().assert_memory_released();
                        }
                    }
                }
            }
        }
        // Complete values and ownership precede the read-growth assertion.
        assert!(
            growth.chunks_exact(4).all(|group| group[3] <= 3 * group[2]),
            "native field maps must avoid unrelated group rereads: {growth:?}"
        );
    }

    #[test]
    fn aggregate_label_borrows_outlive_machines_and_materialize_at_descriptor_boundaries() {
        use crate::{evaluator::EvaluatedSample, sample_labels::SampleLabels};

        for (expression, expected_labels, value_factor) in [
            ("abs(sum by(instance)(counter_total))", 1, 1.0),
            ("topk(2,sum by(instance)(counter_total))", 1, 1.0),
            ("bottomk(2,sum by(instance)(counter_total))", 1, 1.0),
            ("abs(topk(2,sum by(instance)(counter_total)))", 1, 1.0),
            (
                "label_join(topk(2,sum by(instance)(counter_total)), \"row\", \"/\", \"instance\")",
                2,
                1.0,
            ),
            (
                "label_join(abs(sum by(instance)(counter_total)), \"row\", \"/\", \"instance\")",
                2,
                1.0,
            ),
            (
                "sum by(instance)(counter_total) + on(instance) sum by(instance)(counter_total)",
                1,
                2.0,
            ),
            (
                "sum by(instance)(counter_total) or sum by(instance)(counter_total)",
                1,
                1.0,
            ),
            ("quantile by(instance)(0.5,counter_total)", 1, 0.5),
            ("abs(quantile by(instance)(0.5,counter_total))", 1, 0.5),
            (
                "label_join(quantile by(instance)(0.5,counter_total), \"row\", \"/\", \"instance\")",
                2,
                0.5,
            ),
        ] {
            for delayed in [false, true] {
                for page in [1, 17, 1024] {
                    let (collected, retained) = {
                        let input = mapped_group_provider(page, 2);
                        let engine = Engine::default();
                        let control = Control::default();
                        let query = engine
                            .compile(expression.as_bytes(), options(delayed), &control)
                            .unwrap();
                        let request = QueryRequest::Range {
                            start_ms: 1000,
                            end_ms: 2000,
                            step_ms: 1000,
                        };
                        let account = query.execution_accounting();
                        {
                            let header = query.header(request).unwrap();
                            let prepared = Prepared::new(
                                &query.expression,
                                &query.preprocessing,
                                header,
                                query.options.no_step_subquery_interval_ms,
                                &control,
                                &account,
                            )
                            .unwrap();
                            let header = prepared.evaluator_header();
                            prepared.activate(header, &control, &account).unwrap();
                            let options =
                                query.evaluation_options(header, header.start_ms, &prepared);
                            let bounds = crate::query_bounds::find(
                                &query.expression,
                                options,
                                &prepared,
                                &control,
                                &account,
                            )
                            .unwrap();
                            let scope = input.open(bounds, &control).unwrap();
                            let catalog = Catalog::new(
                                &scope,
                                &query.expression,
                                &prepared,
                                options,
                                query.options.no_step_subquery_interval_ms,
                                &control,
                                &account,
                            )
                            .unwrap();
                            let rosters = query
                                .prepare_rosters(
                                    &catalog,
                                    &prepared,
                                    bounds,
                                    &control,
                                    &account,
                                    &mut Annotations::default(),
                                )
                                .unwrap();
                            let metadata = || EvaluationMetadata {
                                prepared: &prepared,
                                rosters: &rosters,
                                timestamp_selectors: &query.timestamp_selectors,
                                data_bounds: bounds,
                                annotations: None,
                                binary_preparation: None,
                                histogram_preparation: None,
                                info_preparation: None,
                                count_preparation: None,
                            };
                            let mut machine = Machine::new(
                                &catalog,
                                &query.expression,
                                query.expression.root,
                                options,
                                &control,
                                &account,
                                metadata(),
                            );
                            let first = machine.next().unwrap().unwrap();
                            let second = machine.next().unwrap().unwrap();
                            assert!(machine.next().unwrap().is_none());
                            drop(machine);
                            assert!(
                                matches!(first.labels, SampleLabels::Borrowed(_)),
                                "immutable result labels must borrow their frozen owner: {expression}"
                            );
                            assert!(matches!(second.labels, SampleLabels::Borrowed(_)));
                            assert_eq!(first.labels.0.len(), expected_labels);
                            if expected_labels == 2 {
                                assert_eq!(first.labels.0[1].name.as_ref(), b"row");
                                assert_eq!(first.labels.0[1].value, first.labels.0[0].value);
                                rosters.clear_replay_progress(&control, &account).unwrap();
                                prepared.range_folds.clear(&control, &account).unwrap();
                                let mut calibration = Machine::new(
                                    &catalog,
                                    &query.expression,
                                    query.expression.root,
                                    options,
                                    &control,
                                    &account,
                                    metadata(),
                                );
                                calibration.bypass_root_order();
                                let before = account.snapshot().work;
                                assert!(calibration.next().unwrap().is_some());
                                let final_work = account.snapshot().work - before;
                                assert!(final_work > 0);
                                drop(calibration);
                                rosters.clear_replay_progress(&control, &account).unwrap();
                                prepared.range_folds.clear(&control, &account).unwrap();
                                let cancelled = Control::default();
                                let mut interrupted = Machine::new(
                                    &catalog,
                                    &query.expression,
                                    query.expression.root,
                                    options,
                                    &cancelled,
                                    &account,
                                    metadata(),
                                );
                                interrupted.bypass_root_order();
                                let before = account.snapshot().work;
                                let result = crate::test_storage::interrupt_after_work(
                                    &account,
                                    &cancelled,
                                    final_work,
                                    || interrupted.next(),
                                );
                                assert_eq!(account.snapshot().work - before, final_work);
                                assert_eq!(
                                    result.map(|_| ()),
                                    Err(EvaluationError::Interrupted(Interrupted::Cancelled))
                                );
                                drop(interrupted);
                            }
                            assert_eq!(first.labels.0[0].name.as_ref(), b"instance");
                            assert_ne!(first.labels.0[0].value, second.labels.0[0].value);

                            let hash =
                                crate::label_hash::full(&first.labels, &control, &account).unwrap();
                            let make_sample = || EvaluatedSample {
                                ordinal: first.ordinal,
                                labels: SampleLabels::Borrowed(first.labels.as_ref()),
                                value: OwnedValue::Float(1.0),
                                float_samples: None,
                                source_time_ms: first.source_time_ms,
                                source_start_time_ms: 0,
                                drop_name: first.drop_name,
                            };
                            let record =
                                |descriptors: &mut AccountedVec<Descriptor>,
                                 index: &mut DescriptorIndex,
                                 control: &Control| {
                                    query.record_descriptor(
                                        query.expression.root,
                                        (make_sample(), hash),
                                        (descriptors, index),
                                        (&prepared, &rosters),
                                        control,
                                        &account,
                                    )
                                };
                            let mut descriptors =
                                AccountedVec::new(&account, MemoryKind::Workspace);
                            let mut index = DescriptorIndex::new(&account);
                            let before = account.snapshot().work;
                            assert_eq!(record(&mut descriptors, &mut index, &control).unwrap(), 0);
                            let conversion_work = account.snapshot().work - before;
                            assert!(conversion_work > 0);
                            assert_eq!(descriptors.len(), 1);
                            assert!(descriptors[0].labels.same(&first.labels));
                            assert_ne!(descriptors[0].labels.0.as_ptr(), first.labels.0.as_ptr());
                            let before = account.snapshot().memory;
                            assert_eq!(record(&mut descriptors, &mut index, &control).unwrap(), 0);
                            assert_eq!(
                                account.snapshot().memory,
                                before,
                                "existing descriptor must not copy labels"
                            );
                            drop((descriptors, index));

                            let before = account.snapshot().memory;
                            let mut descriptors =
                                AccountedVec::new(&account, MemoryKind::Workspace);
                            let mut index = DescriptorIndex::new(&account);
                            let cancelled = Control::default();
                            let error = crate::test_storage::interrupt_after_work(
                                &account,
                                &cancelled,
                                conversion_work,
                                || record(&mut descriptors, &mut index, &cancelled),
                            )
                            .unwrap_err();
                            assert_eq!(error, EvaluationError::Interrupted(Interrupted::Cancelled));
                            assert!(descriptors.is_empty());
                            // The provisional index exists before conversion; failure discards the whole local owner.
                            let probe = account.snapshot().work;
                            assert!(
                                index
                                    .find(
                                        first.ordinal + 1,
                                        &first.labels,
                                        &descriptors,
                                        &control,
                                        &account
                                    )
                                    .unwrap()
                                    .is_none()
                            );
                            assert!(account.snapshot().work > probe);
                            drop((descriptors, index));
                            assert!(
                                account
                                    .snapshot()
                                    .memory
                                    .iter()
                                    .zip(before)
                                    .all(|(now, old)| now.current == old.current)
                            );
                            let mut descriptors =
                                AccountedVec::new(&account, MemoryKind::Workspace);
                            let mut index = DescriptorIndex::new(&account);
                            assert_eq!(record(&mut descriptors, &mut index, &control).unwrap(), 0);
                            assert!(descriptors[0].labels.same(&first.labels));
                        }
                        input.assert_closed();
                        account.snapshot().assert_memory_released();
                        drop(account);
                        let (result, _) = query.collect(&input, request, &control).unwrap();
                        input.assert_closed();
                        (result, engine.accounting.clone())
                    };
                    assert_eq!(collected.series.len(), 2);
                    for (group, row) in collected.series.iter().enumerate() {
                        assert_eq!(
                            row.labels.0[0].value.as_ref(),
                            format!("g{group:04}").as_bytes()
                        );
                        assert_eq!(row.labels.0.len(), expected_labels);
                        if expected_labels == 2 {
                            assert_eq!(row.labels.0[1].name.as_ref(), b"row");
                            assert_eq!(row.labels.0[1].value, row.labels.0[0].value);
                        }
                        assert_eq!(row.points.len(), 2);
                        for (tick, point) in row.points.iter().enumerate() {
                            assert_eq!(point.time_ms, (tick as i64 + 1) * 1000);
                            assert_eq!(
                                float_bits(point),
                                (value_factor * 2.0 * (group + 1) as f64 * (tick + 1) as f64)
                                    .to_bits()
                            );
                        }
                    }
                    drop(collected);
                    retained.snapshot().assert_memory_released();
                }
            }
        }
    }

    #[test]
    fn projected_groups_check_complete_results_before_bounded_source_reads() {
        let mut scaling = Vec::new();
        let mut complete = 0;
        for delayed in [false, true] {
            for page in [1, 17, 1024] {
                for window in [false, true] {
                    let body = if window {
                        "rate(counter_total[3s])"
                    } else {
                        "counter_total"
                    };
                    let aggregate = format!("sum by(instance)({body})");
                    let join = format!("label_join({aggregate},\"row\",\"/\",\"instance\")");
                    let replace =
                        format!("label_replace({aggregate},\"row\",\"$1\",\"instance\",\"(.*)\")");
                    let expressions = [
                        join.clone(),
                        replace.clone(),
                        format!("abs({join})"),
                        format!("label_join({replace},\"alias\",\"/\",\"instance\")"),
                    ];
                    for (request_index, request) in [
                        QueryRequest::Instant { time_ms: 3000 },
                        QueryRequest::Range {
                            start_ms: 3000,
                            end_ms: 3000,
                            step_ms: 1000,
                        },
                        QueryRequest::Range {
                            start_ms: 3000,
                            end_ms: 5000,
                            step_ms: 1000,
                        },
                    ]
                    .into_iter()
                    .enumerate()
                    {
                        for (shape, expression) in expressions.iter().enumerate() {
                            let mut reads = Vec::new();
                            for groups in [2, 4, 8, 16] {
                                let provider = mapped_group_provider(page, groups);
                                let engine = Engine::default();
                                let control = Control::default();
                                let query = engine
                                    .compile(expression.as_bytes(), options(delayed), &control)
                                    .unwrap();
                                let report = query.collect_reported(&provider, request, &control);
                                let result = report.result.as_ref().unwrap();
                                assert!(report.annotations.is_empty());
                                assert_eq!(result.series.len(), groups);
                                let points = if request_index == 2 { 3 } else { 1 };
                                let mut seen = vec![false; groups];
                                for (position, row) in result.series.iter().enumerate() {
                                    let instance = row
                                        .labels
                                        .0
                                        .iter()
                                        .find(|label| &*label.name == b"instance")
                                        .unwrap();
                                    let group = std::str::from_utf8(&instance.value).unwrap()[1..]
                                        .parse::<usize>()
                                        .unwrap();
                                    assert!(group < groups && !seen[group]);
                                    seen[group] = true;
                                    if request_index != 0 {
                                        assert_eq!(group, position);
                                    }
                                    assert_eq!(row.labels.0.len(), if shape == 3 { 3 } else { 2 });
                                    let expected = format!("g{group:04}");
                                    for label in &*row.labels.0 {
                                        assert!(matches!(
                                            &*label.name,
                                            b"instance" | b"row" | b"alias"
                                        ));
                                        assert_eq!(&*label.value, expected.as_bytes());
                                    }
                                    assert_eq!(row.points.len(), points);
                                    for (tick, point) in row.points.iter().enumerate() {
                                        assert_eq!(point.time_ms, (tick as i64 + 3) * 1000);
                                        let scale = if group % 2 == 0 { 2.0 } else { 4.0 };
                                        let expected = if window {
                                            scale
                                        } else {
                                            scale * (tick + 3) as f64
                                        };
                                        assert_eq!(float_bits(point), expected.to_bits());
                                    }
                                }
                                assert!(seen.into_iter().all(|present| present));
                                assert_eq!(
                                    report.observations.output_samples,
                                    (points * groups) as u64
                                );
                                assert_eq!(
                                    report.observations.memory[MemoryKind::Workspace as usize]
                                        .current,
                                    0
                                );
                                reads.push(report.observations.samples_fetched);
                                provider.assert_closed();
                                drop((report, query));
                                engine.accounting.snapshot().assert_memory_released();
                                complete += 1;
                            }
                            scaling.push((delayed, page, window, request_index, shape, reads));
                        }
                    }
                }
            }
        }
        assert_eq!(complete, 576);
        println!("complete projected-group outcomes={complete}; source reads={scaling:?}");
        // Check growth only after every full numerical and ownership outcome has passed.
        for (delayed, page, window, request, shape, reads) in scaling {
            if !window {
                assert!(
                    reads[3] <= reads[2] * 3,
                    "quadratic projection reads: delayed={delayed} page={page} request={request} shape={shape} reads={reads:?}"
                );
            }
        }
    }

    fn mapped_float_report_snapshot(
        report: &ExecutionReport<crate::result::CollectedResult>,
    ) -> String {
        let annotations = |values: &Annotations| {
            values
                .iter()
                .map(|value| {
                    format!(
                        "{:?}",
                        (
                            value.kind,
                            value.severity,
                            value.raw_message,
                            value.message,
                            value.span,
                            value.occurrences,
                        )
                    )
                })
                .collect::<Vec<_>>()
        };
        let result = report.result.as_ref().map(|result| {
            let rows = result
                .series
                .iter()
                .map(|row| {
                    (
                        row.series_id,
                        row.labels
                            .0
                            .iter()
                            .map(|label| (label.name.to_vec(), label.value.to_vec()))
                            .collect::<Vec<_>>(),
                        row.points
                            .iter()
                            .map(|point| (point.time_ms, float_bits(point)))
                            .collect::<Vec<_>>(),
                    )
                })
                .collect::<Vec<_>>();
            (
                format!("{:?}", result.header),
                result.scalar.map(|(time, value)| (time, value.to_bits())),
                result
                    .string
                    .as_ref()
                    .map(|(time, value)| (*time, value.to_vec())),
                rows,
                annotations(&result.annotations),
            )
        });
        let result = result.map_err(|error| match error {
            ExecutionError::Evaluation(EvaluationError::Storage(StorageError::Provider(bytes))) => {
                format!("Evaluation(Storage(Provider({:?})))", &**bytes)
            }
            other => panic!("unexpected fixture error: {other:?}"),
        });
        format!("{result:?} {:?}", annotations(&report.annotations))
    }

    #[test]
    fn mapped_ranges_keep_nested_map_materialization_on_the_owned_path() {
        for function in [
            "rate",
            "increase",
            "delta",
            "irate",
            "idelta",
            "sum_over_time",
            "avg_over_time",
            "min_over_time",
            "max_over_time",
            "count_over_time",
            "present_over_time",
            "stdvar_over_time",
            "stddev_over_time",
        ] {
            for aggregate in [false, true] {
                let child = format!("abs(abs({function}(counter_total[3s])))");
                let expression = if aggregate {
                    format!("sum by(instance)({child})")
                } else {
                    child
                };
                for page in [1, 17, 1024] {
                    for delayed in [false, true] {
                        let mut outputs = Vec::new();
                        let mut resources = Vec::new();
                        for skip in [true, false] {
                            let mut provider = mapped_group_provider(page, 2);
                            for row in &mut provider.series {
                                row.labels.extend([
                                    (b"__type__".to_vec(), b"counter".to_vec()),
                                    (b"__unit__".to_vec(), b"raw".to_vec()),
                                    (b"empty".to_vec(), Vec::new()),
                                ]);
                                row.labels.sort_by(|left, right| left.0.cmp(&right.0));
                            }
                            let engine = Engine::default();
                            let control = Control::default();
                            let query = engine
                                .compile(expression.as_bytes(), options(delayed), &control)
                                .unwrap();
                            let (report, counts) =
                                crate::evaluator::observe_mapped_labels(skip, || {
                                    query.collect_reported(
                                        &provider,
                                        QueryRequest::Range {
                                            start_ms: 3000,
                                            end_ms: 5000,
                                            step_ms: 1000,
                                        },
                                        &control,
                                    )
                                });
                            assert_eq!(counts, [0, 0, 0], "{expression}");
                            assert_eq!(
                                report.result.as_ref().unwrap().series.len(),
                                if aggregate { 2 } else { 4 }
                            );
                            outputs.push(mapped_float_report_snapshot(&report));
                            resources.push((
                                report.observations.work,
                                report
                                    .observations
                                    .memory
                                    .iter()
                                    .map(|m| (m.current, m.peak, m.acquired, m.released))
                                    .collect::<Vec<_>>(),
                            ));
                            provider.assert_closed();
                            drop((report, query));
                            engine.accounting.snapshot().assert_memory_released();
                        }
                        assert_eq!(outputs[0], outputs[1]);
                        assert_eq!(resources[0], resources[1]);
                    }
                }
            }
        }
    }

    #[test]
    fn mapped_ranges_borrow_complete_labels_with_child_metadata_projection() {
        let mut pairs = 0;
        for function in [
            "rate",
            "increase",
            "delta",
            "irate",
            "idelta",
            "sum_over_time",
            "avg_over_time",
        ] {
            for shape in 0..8 {
                let child = format!("{function}(counter_total[3s])");
                let threshold = match function {
                    "sum_over_time" => 9.0,
                    "avg_over_time" => 3.0,
                    "increase" | "delta" => 4.5,
                    _ => 1.5,
                };
                let parameter = format!("scalar(vector({threshold}))");
                let expression = match shape {
                    0 => format!("{child}/3"),
                    1 => format!("3/{child}"),
                    2 => format!("abs({child})"),
                    3 => format!("ceil({child})"),
                    4 => format!("{child}>{parameter}"),
                    5 => format!("{child}>bool {parameter}"),
                    6 => format!("{parameter}<{child}"),
                    _ => format!("{parameter}<bool {child}"),
                };
                for delayed in [false, true] {
                    for page in [1, 17, 1024] {
                        let mut outcomes = Vec::new();
                        let mut resources = Vec::new();
                        let owned_root =
                            delayed && matches!(function, "sum_over_time" | "avg_over_time");
                        for skip in [true, false] {
                            let mut provider = mapped_group_provider(page, 2);
                            for row in &mut provider.series {
                                row.labels.extend([
                                    (b"__type__".to_vec(), b"counter".to_vec()),
                                    (b"__unit__".to_vec(), b"KiB".to_vec()),
                                    (b"empty".to_vec(), Vec::new()),
                                ]);
                                row.labels.sort_by(|left, right| left.0.cmp(&right.0));
                            }
                            let engine = Engine::default();
                            let control = Control::default();
                            let query = engine
                                .compile(expression.as_bytes(), options(delayed), &control)
                                .unwrap();
                            let (report, counts) =
                                crate::evaluator::observe_mapped_labels(skip, || {
                                    query.collect_reported(
                                        &provider,
                                        QueryRequest::Range {
                                            start_ms: 3000,
                                            end_ms: 5000,
                                            step_ms: 1000,
                                        },
                                        &control,
                                    )
                                });
                            let result = report.result.as_ref().unwrap();
                            assert!(report.annotations.is_empty());
                            if owned_root {
                                assert_eq!(counts, [0, 0, 0]);
                            } else {
                                assert!(counts[0] > 0, "{expression}: no eligible owner");
                            }
                            if !skip && !owned_root {
                                assert!(
                                    counts[1] > 0 && counts[2] == 0,
                                    "{expression}: {counts:?}"
                                );
                            }
                            assert_eq!(
                                result.series.len(),
                                if matches!(shape, 4 | 6)
                                    && !matches!(function, "sum_over_time" | "avg_over_time")
                                {
                                    2
                                } else {
                                    4
                                }
                            );
                            for row in &*result.series {
                                let labels = row
                                    .labels
                                    .0
                                    .iter()
                                    .map(|label| (&*label.name, &*label.value))
                                    .collect::<Vec<_>>();
                                assert_eq!(
                                    labels.iter().map(|(key, _)| *key).collect::<Vec<_>>(),
                                    [
                                        b"empty".as_slice(),
                                        b"instance".as_slice(),
                                        b"member".as_slice()
                                    ]
                                );
                                assert_eq!(labels[0].1, b"");
                                assert!(matches!(labels[1].1, b"g0000" | b"g0001"));
                                assert!(matches!(labels[2].1, b"0" | b"1"));
                                let scale = if labels[1].1 == b"g0000" { 1.0 } else { 2.0 };
                                let expected = (3..=5)
                                    .filter_map(|time| {
                                        let value = scale
                                            * match function {
                                                "sum_over_time" => (time - 1) as f64 * 3.0,
                                                "avg_over_time" => (time - 1) as f64,
                                                "increase" | "delta" => 3.0,
                                                _ => 1.0,
                                            };
                                        if matches!(shape, 4 | 6) && value <= threshold {
                                            return None;
                                        }
                                        let mapped: f64 = match shape {
                                            0 => value / 3.0,
                                            1 => 3.0 / value,
                                            5 | 7 => f64::from(value > threshold),
                                            _ => value,
                                        };
                                        Some((time * 1000, mapped.to_bits()))
                                    })
                                    .collect::<Vec<_>>();
                                assert_eq!(
                                    row.points
                                        .iter()
                                        .map(|point| (point.time_ms, float_bits(point)))
                                        .collect::<Vec<_>>(),
                                    expected
                                );
                            }
                            outcomes.push(mapped_float_report_snapshot(&report));
                            resources.push((
                                report.observations.work,
                                report
                                    .observations
                                    .memory
                                    .iter()
                                    .map(|m| (m.current, m.peak, m.acquired, m.released))
                                    .collect::<Vec<_>>(),
                            ));
                            provider.assert_closed();
                            drop((report, query));
                            engine.accounting.snapshot().assert_memory_released();
                        }
                        assert_eq!(
                            outcomes[0], outcomes[1],
                            "{expression} delayed={delayed} page={page}"
                        );
                        if owned_root {
                            assert_eq!(resources[0], resources[1]);
                        }
                        pairs += 1;
                    }
                }
            }
        }
        assert_eq!(pairs, 336);
    }

    #[test]
    fn mapped_reducers_borrow_labels_with_independent_values_and_membership() {
        let mut pairs = 0;
        for function in [
            "min_over_time",
            "max_over_time",
            "count_over_time",
            "present_over_time",
            "stdvar_over_time",
            "stddev_over_time",
        ] {
            for aggregate in [false, true] {
                for shape in 0..8 {
                    let child = format!("{function}(counter_total[3s])");
                    let threshold = match function {
                        "min_over_time" | "count_over_time" => 2.5,
                        "max_over_time" => 4.5,
                        "present_over_time" => 0.5,
                        "stdvar_over_time" => 1.5,
                        _ => 1.1,
                    };
                    let parameter = format!("scalar(vector({threshold}))");
                    let mapped = match shape {
                        0 => format!("{child}/3"),
                        1 => format!("3/{child}"),
                        2 => format!("abs({child})"),
                        3 => format!("ceil({child})"),
                        4 => format!("{child}>{parameter}"),
                        5 => format!("{child}>bool {parameter}"),
                        6 => format!("{parameter}<{child}"),
                        _ => format!("{parameter}<bool {child}"),
                    };
                    let expression = if aggregate {
                        format!("sum by(instance)({mapped})")
                    } else {
                        mapped
                    };
                    for delayed in [false, true] {
                        for page in [1, 17, 1024] {
                            let mut outputs = Vec::new();
                            let mut resources = Vec::new();
                            let owned_root = delayed && !aggregate;
                            for skip in [true, false] {
                                let mut provider = mapped_group_provider(page, 2);
                                for row in &mut provider.series {
                                    row.labels.extend([
                                        (b"__type__".to_vec(), b"gauge".to_vec()),
                                        (b"__unit__".to_vec(), b"KiB".to_vec()),
                                        (b"empty".to_vec(), Vec::new()),
                                    ]);
                                    row.labels.sort_by(|a, b| a.0.cmp(&b.0));
                                }
                                let engine = Engine::default();
                                let control = Control::default();
                                let query = engine
                                    .compile(expression.as_bytes(), options(delayed), &control)
                                    .unwrap();
                                let (report, counts) =
                                    crate::evaluator::observe_mapped_labels(skip, || {
                                        query.collect_reported(
                                            &provider,
                                            QueryRequest::Range {
                                                start_ms: 3000,
                                                end_ms: 5000,
                                                step_ms: 1000,
                                            },
                                            &control,
                                        )
                                    });
                                let result = report.result.as_ref().unwrap();
                                assert!(report.annotations.is_empty());
                                if owned_root {
                                    assert_eq!(counts, [0, 0, 0]);
                                } else {
                                    assert!(counts[0] > 0, "{expression}: {counts:?}");
                                    if !skip {
                                        assert!(
                                            counts[1] > 0 && counts[2] == 0,
                                            "{expression}: {counts:?}"
                                        );
                                    }
                                }
                                let mut expected = Vec::new();
                                for group in 0..2 {
                                    let scale = (group + 1) as f64;
                                    let points = (3..=5)
                                        .filter_map(|time| {
                                            let value = match function {
                                                "min_over_time" => (time - 2) as f64 * scale,
                                                "max_over_time" => time as f64 * scale,
                                                "count_over_time" => 3.0,
                                                "present_over_time" => 1.0,
                                                "stdvar_over_time" => (2.0 / 3.0) * scale * scale,
                                                // Population deviation of three consecutive integers.
                                                _ => 0.816_496_580_927_726 * scale,
                                            };
                                            if matches!(shape, 4 | 6) && value <= threshold {
                                                return None;
                                            }
                                            let value = match shape {
                                                0 => value / 3.0,
                                                1 => 3.0 / value,
                                                3 => value.ceil(),
                                                5 | 7 => f64::from(value > threshold),
                                                _ => value,
                                            };
                                            Some((
                                                time * 1000,
                                                (if aggregate { value + value } else { value })
                                                    .to_bits(),
                                            ))
                                        })
                                        .collect::<Vec<_>>();
                                    if points.is_empty() {
                                        continue;
                                    }
                                    for member in 0..if aggregate { 1 } else { 2 } {
                                        let mut labels = vec![(
                                            b"instance".to_vec(),
                                            format!("g{group:04}").into_bytes(),
                                        )];
                                        if !aggregate {
                                            labels.insert(0, (b"empty".to_vec(), Vec::new()));
                                            labels.push((
                                                b"member".to_vec(),
                                                member.to_string().into_bytes(),
                                            ));
                                        }
                                        expected.push((labels, points.clone()));
                                    }
                                }
                                let mut actual = result
                                    .series
                                    .iter()
                                    .map(|row| {
                                        (
                                            row.labels
                                                .0
                                                .iter()
                                                .map(|l| (l.name.to_vec(), l.value.to_vec()))
                                                .collect::<Vec<_>>(),
                                            row.points
                                                .iter()
                                                .map(|p| (p.time_ms, float_bits(p)))
                                                .collect::<Vec<_>>(),
                                        )
                                    })
                                    .collect::<Vec<_>>();
                                actual.sort();
                                expected.sort();
                                assert_eq!(
                                    actual, expected,
                                    "{expression} delayed={delayed} page={page}"
                                );
                                outputs.push(mapped_float_report_snapshot(&report));
                                resources.push((
                                    report.observations.work,
                                    report
                                        .observations
                                        .memory
                                        .iter()
                                        .map(|m| (m.current, m.peak, m.acquired, m.released))
                                        .collect::<Vec<_>>(),
                                ));
                                provider.assert_closed();
                                drop((report, query));
                                engine.accounting.snapshot().assert_memory_released();
                            }
                            assert_eq!(outputs[0], outputs[1]);
                            if owned_root {
                                assert_eq!(resources[0], resources[1]);
                            }
                            pairs += 1;
                        }
                    }
                }
            }
        }
        assert_eq!(pairs, 576);
    }

    #[test]
    fn mapped_reducers_preserve_mixed_diagnostics_and_native_counts() {
        use crate::annotations::AnnotationKind;
        fn sample<const STATE: u8>(index: usize) -> crate::value::Sample {
            let mut point = native_range_sample(index % 3);
            point.time_ms = (index as i64 + 1) * 1000;
            point.start_time_ms = 0;
            if STATE != 2 && !(STATE == 1 && index % 3 == 1) {
                point.value = crate::value::SampleValue::Float(if STATE == 3 {
                    f64::from_bits(0x7ff0_0000_0000_0002)
                } else {
                    (index % 3 + 1) as f64
                });
            }
            point
        }
        for function in [
            "min_over_time",
            "max_over_time",
            "count_over_time",
            "present_over_time",
            "stdvar_over_time",
            "stddev_over_time",
        ] {
            for state in 0..6 {
                for delayed in [false, true] {
                    for page in [1, 17, 1024] {
                        let mut outputs = Vec::new();
                        for skip in [true, false] {
                            let mut provider = mapped_group_provider(page, 2);
                            for row in &mut provider.series {
                                row.source.count = match state {
                                    4 => 0,
                                    5 => 1,
                                    _ => 5,
                                };
                                row.source.sample = match state {
                                    1 => sample::<1>,
                                    2 => sample::<2>,
                                    3 => sample::<3>,
                                    _ => sample::<0>,
                                };
                            }
                            let engine = Engine::default();
                            let control = Control::default();
                            let source =
                                format!("sum by(instance)(abs({function}(counter_total[3s])))");
                            let query = engine
                                .compile(source.as_bytes(), options(delayed), &control)
                                .unwrap();
                            let (report, counts) =
                                crate::evaluator::observe_mapped_labels(skip, || {
                                    query.collect_reported(
                                        &provider,
                                        QueryRequest::Range {
                                            start_ms: 3000,
                                            end_ms: 5000,
                                            step_ms: 1000,
                                        },
                                        &control,
                                    )
                                });
                            let result = report.result.as_ref().unwrap();
                            let expected: Option<f64> = match (function, state) {
                                (_, 3 | 4) => None,
                                ("count_over_time", 5) => Some(1.0),
                                ("count_over_time", _) => Some(3.0),
                                ("present_over_time", _) => Some(1.0),
                                (_, 2) => None,
                                ("stdvar_over_time" | "stddev_over_time", 5) => Some(0.0),
                                (_, 5) | ("min_over_time", _) => Some(1.0),
                                ("max_over_time", _) => Some(3.0),
                                (_, 1) => Some(1.0),
                                ("stdvar_over_time", _) => Some(2.0 / 3.0),
                                _ => Some(0.816_496_580_927_726),
                            };
                            assert_eq!(result.series.len(), if expected.is_some() { 2 } else { 0 });
                            if let Some(value) = expected {
                                for row in &*result.series {
                                    assert_eq!(row.labels.0.len(), 1);
                                    assert_eq!(&*row.labels.0[0].name, b"instance");
                                    assert!(matches!(&*row.labels.0[0].value, b"g0000" | b"g0001"));
                                    let times: &[i64] = if state == 5 {
                                        &[3000]
                                    } else {
                                        &[3000, 4000, 5000]
                                    };
                                    assert_eq!(
                                        row.points
                                            .iter()
                                            .map(|point| (point.time_ms, float_bits(point)))
                                            .collect::<Vec<_>>(),
                                        times
                                            .iter()
                                            .map(|time| (*time, (value + value).to_bits()))
                                            .collect::<Vec<_>>()
                                    );
                                }
                                if !skip {
                                    assert!(
                                        counts[1] > 0 && counts[2] == 0,
                                        "{function}/{state}: {counts:?}"
                                    );
                                }
                            } else {
                                assert_eq!(counts, [0, 0, 0]);
                            }
                            let mixed_info = state == 1
                                && !matches!(function, "count_over_time" | "present_over_time");
                            assert_eq!(report.annotations.len(), usize::from(mixed_info));
                            if mixed_info {
                                let annotation = report.annotations.iter().next().unwrap();
                                assert_eq!(
                                    annotation.kind,
                                    AnnotationKind::HistogramIgnoredInMixedRange
                                );
                                let span = annotation.span.unwrap();
                                assert_eq!(&source[span.start..span.end], "counter_total[3s]");
                                let message = r#"PromQL info: ignored histograms in a range containing both floats and histograms for metric name "counter_total""#;
                                assert_eq!(annotation.raw_message, message.as_bytes());
                                assert_eq!(
                                    annotation.message,
                                    format!("{message} (1:{})", span.start + 1).as_bytes()
                                );
                            }
                            outputs.push(mapped_float_report_snapshot(&report));
                            provider.assert_closed();
                            drop((report, query));
                            engine.accounting.snapshot().assert_memory_released();
                        }
                        assert_eq!(
                            outputs[0], outputs[1],
                            "{function}/{state} delayed={delayed} page={page}"
                        );
                    }
                }
            }
        }
    }

    fn typed_rate_family_sample<const STATE: u8>(index: usize) -> crate::value::Sample {
        let mut point = diagnostic_sample(index);
        point.time_ms = [500, 1500, 2500, 4500][index];
        point.value = if (STATE == 3 && index == 0) || (STATE == 4 && index == 2) || STATE == 5 {
            native_range_sample(index).value
        } else {
            crate::value::SampleValue::Float(match STATE {
                1 => [10.0, 20.0, 2.0, 4.0][index],
                2 => [2.0, 5.0, 11.0, 3.0][index],
                6 => [-10.0, -4.0, 3.0, -5.0][index],
                _ => [2.0, 5.0, 11.0, 17.0][index],
            })
        };
        point
    }

    #[test]
    fn mapped_ranges_preserve_typed_endpoints_and_irregular_reset_values() {
        use crate::annotations::AnnotationKind;
        let mut pairs = 0;
        for function in ["delta", "irate", "idelta", "sum_over_time", "avg_over_time"] {
            for state in 0..if matches!(function, "sum_over_time" | "avg_over_time") {
                7
            } else {
                6
            } {
                let expected: Option<f64> = match (function, state) {
                    (_, 4 | 5) | ("delta" | "sum_over_time" | "avg_over_time", 3) => None,
                    ("sum_over_time", 0) => Some(35.0),
                    ("sum_over_time", 1) => Some(36.0),
                    ("sum_over_time", 2) => Some(21.0),
                    ("sum_over_time", 6) => Some(-16.0),
                    ("avg_over_time", 0) => Some(8.75),
                    ("avg_over_time", 1) => Some(9.0),
                    ("avg_over_time", 2) => Some(5.25),
                    ("avg_over_time", 6) => Some(-4.0),
                    ("delta", 0) => Some(16.875),
                    ("delta", 1) => Some(-6.75),
                    ("delta", 2) => Some(1.125),
                    ("irate", 0 | 3) => Some(3.0),
                    ("irate", 1) => Some(1.0),
                    ("irate", 2) => Some(1.5),
                    ("idelta", 0 | 3) => Some(6.0),
                    ("idelta", 1) => Some(2.0),
                    ("idelta", 2) => Some(-8.0),
                    _ => unreachable!(),
                };
                for delayed in [false, true] {
                    for page in [1, 17, 1024] {
                        let mut outputs = Vec::new();
                        let mut resources = Vec::new();
                        let owned_root =
                            delayed && matches!(function, "sum_over_time" | "avg_over_time");
                        for skip in [true, false] {
                            let mut provider = mapped_group_provider(page, 1);
                            for row in &mut provider.series {
                                row.labels[0].1 = b"m".to_vec();
                                row.source.count = 4;
                                row.source.sample = match state {
                                    0 => typed_rate_family_sample::<0>,
                                    1 => typed_rate_family_sample::<1>,
                                    2 => typed_rate_family_sample::<2>,
                                    3 => typed_rate_family_sample::<3>,
                                    4 => typed_rate_family_sample::<4>,
                                    5 => typed_rate_family_sample::<5>,
                                    _ => typed_rate_family_sample::<6>,
                                };
                            }
                            let engine = Engine::default();
                            let control = Control::default();
                            let query = engine
                                .compile(
                                    format!("abs({function}(m[4500ms]))").as_bytes(),
                                    options(delayed),
                                    &control,
                                )
                                .unwrap();
                            let (report, counts) =
                                crate::evaluator::observe_mapped_labels(skip, || {
                                    query.collect_reported(
                                        &provider,
                                        QueryRequest::Range {
                                            start_ms: 4500,
                                            end_ms: 4501,
                                            step_ms: 1,
                                        },
                                        &control,
                                    )
                                });
                            let result = report.result.as_ref().unwrap();
                            assert!(
                                !report
                                    .annotations
                                    .iter()
                                    .any(|a| a.kind == AnnotationKind::PossibleNonCounter)
                            );
                            let mixed = state == 4
                                || (matches!(
                                    function,
                                    "delta" | "sum_over_time" | "avg_over_time"
                                ) && state == 3);
                            assert_eq!(
                                report
                                    .annotations
                                    .iter()
                                    .any(|a| a.kind == AnnotationKind::MixedFloatsHistograms),
                                mixed
                            );
                            assert_eq!(result.series.len(), if expected.is_some() { 2 } else { 0 });
                            if let Some(expected) = expected {
                                if owned_root {
                                    assert_eq!(counts, [0, 0, 0]);
                                } else {
                                    assert!(counts[0] > 0, "{function}/{state}: {counts:?}");
                                }
                                if !skip && !owned_root {
                                    assert!(counts[1] > 0 && counts[2] == 0);
                                }
                                for row in &*result.series {
                                    assert_eq!(
                                        row.points
                                            .iter()
                                            .map(|p| (p.time_ms, float_bits(p)))
                                            .collect::<Vec<_>>(),
                                        [4500, 4501].map(|time| (time, expected.abs().to_bits()))
                                    );
                                }
                            } else {
                                assert_eq!(counts, [0, 0, 0]);
                            }
                            outputs.push(mapped_float_report_snapshot(&report));
                            resources.push((
                                report.observations.work,
                                report
                                    .observations
                                    .memory
                                    .iter()
                                    .map(|m| (m.current, m.peak, m.acquired, m.released))
                                    .collect::<Vec<_>>(),
                            ));
                            provider.assert_closed();
                            drop((report, query));
                            engine.accounting.snapshot().assert_memory_released();
                        }
                        assert_eq!(
                            outputs[0], outputs[1],
                            "{function}/{state}/{delayed}/{page}"
                        );
                        if owned_root {
                            assert_eq!(resources[0], resources[1]);
                        }
                        pairs += 1;
                    }
                }
            }
        }
        assert_eq!(pairs, 192);
    }

    #[test]
    fn mapped_ranges_preserve_window_diagnostics_and_absent_native_results() {
        fn overlap(index: usize) -> crate::value::Sample {
            let mut sample = diagnostic_sample(index);
            sample.start_time_ms = [100, 500, 1500, 2500][index];
            sample
        }
        for function in [
            "rate",
            "increase",
            "sum_over_time",
            "avg_over_time",
            "min_over_time",
            "max_over_time",
            "count_over_time",
            "present_over_time",
            "stdvar_over_time",
            "stddev_over_time",
        ] {
            for page in [1, 17, 1024] {
                for delayed in [false, true] {
                    for state in 0..6 {
                        let mut outcomes = Vec::new();
                        for skip in [true, false] {
                            let mut provider = mapped_group_provider(page, 2);
                            for row in &mut provider.series {
                                row.labels[0].1 = b"m".to_vec();
                                row.source.count = 4;
                                row.source.sample = match state {
                                    1 => overlap,
                                    2 => mixed_range_sample,
                                    3 => native_range_sample,
                                    _ => diagnostic_sample,
                                };
                            }
                            if state == 4 {
                                provider.series[0].source.count = 1;
                            }
                            if state == 5 {
                                provider.series[0].source.fail_page = Some(0);
                            }
                            let engine = Engine::default();
                            let control = Control::default();
                            let query = engine
                                .compile(
                                    format!("sum by(instance)(abs({function}(m[4s])))").as_bytes(),
                                    options(delayed),
                                    &control,
                                )
                                .unwrap();
                            let (report, counts) =
                                crate::evaluator::observe_mapped_labels(skip, || {
                                    query.collect_reported(
                                        &provider,
                                        QueryRequest::Range {
                                            start_ms: 2000,
                                            end_ms: 4000,
                                            step_ms: 1000,
                                        },
                                        &control,
                                    )
                                });
                            if state == 5 {
                                assert!(matches!(&report.result,
                                    Err(ExecutionError::Evaluation(EvaluationError::Storage(StorageError::Provider(bytes))))
                                    if &**bytes == b"injected page failure"));
                            } else {
                                assert!(report.result.is_ok());
                                if matches!(state, 0 | 1 | 4) {
                                    assert_eq!(
                                        report.annotations.iter().any(|entry| {
                                            entry.kind
                                        == crate::annotations::AnnotationKind::PossibleNonCounter
                                        }),
                                        matches!(function, "rate" | "increase")
                                    );
                                    if !skip {
                                        assert!(
                                            counts[1] > 0 && counts[2] == 0,
                                            "{function} state={state}: {counts:?}"
                                        );
                                    }
                                }
                            }
                            outcomes.push(mapped_float_report_snapshot(&report));
                            provider.assert_closed();
                            drop((report, query));
                            engine.accounting.snapshot().assert_memory_released();
                        }
                        assert_eq!(
                            outcomes[0], outcomes[1],
                            "{function} state={state} delayed={delayed} page={page}"
                        );
                    }
                }
            }
        }
    }

    #[test]
    fn comparison_maps_borrow_complete_labels_with_exact_membership_and_metadata() {
        fn sample<const KIND: u8>(index: usize) -> crate::value::Sample {
            let mut sample = crate::test_storage::counter(index);
            sample.value = crate::value::SampleValue::Float(if index == 2 && KIND != 0 {
                f64::from_bits(if KIND == 1 {
                    0x7ff8_0000_0000_0001
                } else {
                    0x7ff0_0000_0000_0002
                })
            } else if index.is_multiple_of(2) {
                1.0
            } else {
                -1.0
            });
            sample
        }
        let mut pairs = 0;
        for operator in ["==", "!=", ">", "<", ">=", "<="] {
            for scalar_left in [false, true] {
                for boolean in [false, true] {
                    for delayed in [false, true] {
                        for page in [1, 17, 1024] {
                            for kind in 0..3 {
                                let threshold = "scalar(vector(time()-3))";
                                let (left, right) = if scalar_left {
                                    (threshold, "m_total")
                                } else {
                                    ("m_total", threshold)
                                };
                                let modifier = if boolean { " bool" } else { "" };
                                let expression = format!("{left} {operator}{modifier} {right}");
                                let mut outcomes = Vec::new();
                                for skip in [true, false] {
                                    let mut provider = comparison_set_provider(page);
                                    for row in provider.series.iter_mut().take(4) {
                                        row.source.sample = match kind {
                                            0 => sample::<0>,
                                            1 => sample::<1>,
                                            _ => sample::<2>,
                                        };
                                        row.labels.extend([
                                            (b"__type__".to_vec(), b"gauge".to_vec()),
                                            (b"__unit__".to_vec(), b"KiB".to_vec()),
                                            (b"empty".to_vec(), Vec::new()),
                                        ]);
                                        row.labels.sort_by(|left, right| left.0.cmp(&right.0));
                                    }
                                    let engine = Engine::default();
                                    let control = Control::default();
                                    let query = engine
                                        .compile(expression.as_bytes(), options(delayed), &control)
                                        .unwrap();
                                    let (report, counts) =
                                        crate::evaluator::observe_mapped_labels(skip, || {
                                            query.collect_reported(
                                                &provider,
                                                QueryRequest::Range {
                                                    start_ms: 1000,
                                                    end_ms: 5000,
                                                    step_ms: 1000,
                                                },
                                                &control,
                                            )
                                        });
                                    let result = report.result.as_ref().unwrap();
                                    assert!(report.annotations.is_empty());
                                    assert_eq!(result.series.len(), 4, "{expression} kind={kind}");
                                    assert!(counts[0] > 0, "{expression}: no eligible completion");
                                    if !skip {
                                        assert!(
                                            counts[1] > 0 && counts[2] == 0,
                                            "{expression}: {counts:?}"
                                        );
                                    }
                                    for (index, row) in result.series.iter().enumerate() {
                                        let identity = index.to_string();
                                        let mut labels = vec![
                                            (b"empty".as_slice(), b"".as_slice()),
                                            (b"instance".as_slice(), identity.as_bytes()),
                                            (b"job".as_slice(), b"worker".as_slice()),
                                        ];
                                        if !boolean {
                                            labels
                                                .splice(
                                                    0..0,
                                                    [
                                                        (
                                                            b"__name__".as_slice(),
                                                            b"m_total".as_slice(),
                                                        ),
                                                        (
                                                            b"__type__".as_slice(),
                                                            b"gauge".as_slice(),
                                                        ),
                                                        (b"__unit__".as_slice(), b"KiB".as_slice()),
                                                    ],
                                                )
                                                .for_each(drop);
                                        }
                                        assert_eq!(
                                            row.labels
                                                .0
                                                .iter()
                                                .map(|label| (&*label.name, &*label.value))
                                                .collect::<Vec<_>>(),
                                            labels
                                        );
                                        let expected = (1..=5)
                                            .filter_map(|tick| {
                                                if tick == 3 && kind == 2 {
                                                    return None;
                                                }
                                                let vector = if tick == 3 && kind == 1 {
                                                    f64::from_bits(0x7ff8_0000_0000_0001)
                                                } else if tick % 2 == 1 {
                                                    1.0
                                                } else {
                                                    -1.0
                                                };
                                                let threshold = tick as f64 - 3.0;
                                                let (left, right) = if scalar_left {
                                                    (threshold, vector)
                                                } else {
                                                    (vector, threshold)
                                                };
                                                let keep = match operator {
                                                    "==" => left == right,
                                                    "!=" => left != right,
                                                    ">" => left > right,
                                                    "<" => left < right,
                                                    ">=" => left >= right,
                                                    "<=" => left <= right,
                                                    _ => unreachable!(),
                                                };
                                                (boolean || keep).then_some((
                                                    tick * 1000,
                                                    if boolean {
                                                        f64::from(keep).to_bits()
                                                    } else {
                                                        vector.to_bits()
                                                    },
                                                ))
                                            })
                                            .collect::<Vec<_>>();
                                        assert_eq!(
                                            row.points
                                                .iter()
                                                .map(|point| (point.time_ms, float_bits(point)))
                                                .collect::<Vec<_>>(),
                                            expected,
                                            "{expression} kind={kind} delayed={delayed} page={page}"
                                        );
                                    }
                                    outcomes.push(mapped_float_report_snapshot(&report));
                                    provider.assert_closed();
                                    drop((report, query));
                                    engine.accounting.snapshot().assert_memory_released();
                                }
                                assert_eq!(outcomes[0], outcomes[1]);
                                pairs += 1;
                            }
                        }
                    }
                }
            }
        }
        assert_eq!(pairs, 432);
    }

    #[test]
    fn comparison_label_borrows_preserve_parameter_diagnostics_and_failures() {
        fn two(index: usize) -> crate::value::Sample {
            crate::value::Sample {
                time_ms: (index as i64 + 1) * 1000,
                start_time_ms: 0,
                value: crate::value::SampleValue::Float(2.0),
            }
        }
        for page in [1, 17, 1024] {
            for delayed in [false, true] {
                for mode in 0..3 {
                    for (scalar_left, boolean) in
                        [(false, false), (true, false), (false, true), (true, true)]
                    {
                        let parameter = if mode == 1 {
                            "scalar(sum(p))"
                        } else {
                            "scalar(min(p))"
                        };
                        let operator = if boolean { "!= bool" } else { "!=" };
                        let child = if scalar_left {
                            format!("{parameter} {operator} counter_total")
                        } else {
                            format!("counter_total {operator} {parameter}")
                        };
                        let mut outputs = Vec::new();
                        for skip in [true, false] {
                            let mut provider = mapped_group_provider(page, 2);
                            let mut parameters = mapped_group_provider(page, 1);
                            for (index, row) in parameters.series.iter_mut().enumerate() {
                                row.labels[0].1 = b"p".to_vec();
                                row.source.sample =
                                    if index == 0 { two } else { native_range_sample };
                                if mode == 2 {
                                    row.source.fail_page = Some(0);
                                }
                            }
                            provider.series.extend(parameters.series);
                            let engine = Engine::default();
                            let control = Control::default();
                            let query = engine
                                .compile(
                                    format!("sum by(instance)({child})").as_bytes(),
                                    options(delayed),
                                    &control,
                                )
                                .unwrap();
                            let (report, counts) =
                                crate::evaluator::observe_mapped_labels(skip, || {
                                    query.collect_reported(
                                        &provider,
                                        QueryRequest::Range {
                                            start_ms: 3000,
                                            end_ms: 5000,
                                            step_ms: 1000,
                                        },
                                        &control,
                                    )
                                });
                            if mode == 2 {
                                assert!(matches!(&report.result,
                                    Err(ExecutionError::Evaluation(EvaluationError::Storage(StorageError::Provider(bytes))))
                                    if &**bytes == b"injected page failure"));
                            } else {
                                assert_eq!(report.result.as_ref().unwrap().series.len(), 2);
                                if !skip {
                                    assert!(counts[1] > 0 && counts[2] == 0, "{child}: {counts:?}");
                                }
                                let expected = if mode == 0 {
                                    crate::annotations::AnnotationKind::HistogramIgnoredInAggregation(TokenKind::MIN)
                                } else {
                                    crate::annotations::AnnotationKind::MixedFloatsHistogramsAggregation
                                };
                                let severity = if mode == 0 {
                                    crate::annotations::Severity::Info
                                } else {
                                    crate::annotations::Severity::Warning
                                };
                                assert!(
                                    report
                                        .annotations
                                        .iter()
                                        .any(|annotation| annotation.kind == expected
                                            && annotation.severity == severity)
                                );
                            }
                            outputs.push(mapped_float_report_snapshot(&report));
                            provider.assert_closed();
                            drop((report, query));
                            engine.accounting.snapshot().assert_memory_released();
                        }
                        assert_eq!(
                            outputs[0], outputs[1],
                            "{child} page={page} delayed={delayed} mode={mode}"
                        );
                    }
                }
            }
        }
    }

    #[test]
    fn scalar_arithmetic_maps_borrow_complete_labels_on_both_sides() {
        let mut children = Vec::new();
        for operator in ["+", "-", "*", "/", "%", "^", "atan2"] {
            children.push(format!("counter_total {operator} 3"));
            children.push(format!("3 {operator} counter_total"));
        }
        children.extend([
            "counter_total/(time()-4)".to_owned(),
            "(time()-4)/counter_total".to_owned(),
        ]);
        let mut complete = 0;
        for child in children {
            for delayed in [false, true] {
                let mut outputs = Vec::new();
                for skip in [true, false] {
                    let provider = mapped_group_provider(17, 2);
                    let engine = Engine::default();
                    let control = Control::default();
                    let query = engine
                        .compile(
                            format!("sum by(instance)({child})").as_bytes(),
                            options(delayed),
                            &control,
                        )
                        .unwrap();
                    let (report, counts) = crate::evaluator::observe_mapped_labels(skip, || {
                        query.collect_reported(
                            &provider,
                            QueryRequest::Range {
                                start_ms: 3000,
                                end_ms: 5000,
                                step_ms: 1000,
                            },
                            &control,
                        )
                    });
                    assert!(report.result.is_ok(), "{child}: {:?}", report.result);
                    assert!(report.annotations.is_empty());
                    assert!(counts[0] > 0, "{child}: no eligible completion");
                    if !skip {
                        assert!(counts[1] > 0 && counts[2] == 0, "{child}: {counts:?}");
                    }
                    outputs.push(mapped_float_report_snapshot(&report));
                    provider.assert_closed();
                    drop((report, query));
                    engine.accounting.snapshot().assert_memory_released();
                }
                assert_eq!(outputs[0], outputs[1], "{child} delayed={delayed}");
                complete += 1;
            }
        }
        assert_eq!(complete, 32);
    }

